export interface ConfigFileFs {
  existsSync(filePath: string): boolean;
  readFileSync(filePath: string): string;
}

const realFs: ConfigFileFs = {
  existsSync: (filePath) => fs.existsSync(filePath),
  readFileSync: (filePath) => fs.readFileSync(filePath, "utf8"),
};

export function resolveConfigFilePath(worktree: string): string {
  return path.join(worktree, ".opencode", "ai-context.config.yaml");
}

function warn(
  filePath: string,
  reason: string,
  onProblem?: (message: string) => void,
): void {
  const message = `ignoring ${filePath}: ${reason}`;
  console.error(`[ai-context] ${message}`);
  onProblem?.(message);
}

/**
 * Reads and validates `.opencode/ai-context.config.yaml` for `worktree`.
 * Returns `{}` (meaning "no overrides from the file") if the file is
 * missing, empty, malformed YAML, not a mapping at the top level, or if
 * a given key is present but the wrong type -- each case logged via
 * `console.error` so a typo isn't silently invisible, but never thrown,
 * so a bad config file degrades to defaults/env-vars-only instead of
 * breaking the whole plugin.
 */

export function loadConfigFile(
  worktree: string,
  fsImpl: ConfigFileFs = realFs,
  onProblem?: (message: string) => void,
): AiContextConfigFile {
  const filePath = resolveConfigFilePath(worktree);
  if (!fsImpl.existsSync(filePath)) return {};

  const content = fsImpl.readFileSync(filePath);
  if (content.trim().length === 0) return {};

  let raw: unknown;
  try {
    raw = parseYaml(content);
  } catch (error) {
    warn(filePath, `malformed YAML (${(error as Error).message})`, onProblem);
    return {};
  }

  if (raw === null || raw === undefined) return {};
  if (typeof raw !== "object" || Array.isArray(raw)) {
    warn(
      filePath,
      "expected a YAML mapping (key: value pairs) at the top level",
      onProblem,
    );
    return {};
  }

  const obj = raw as Record<string, unknown>;
  const config: AiContextConfigFile = {};

  if (obj.enabled !== undefined) {
    if (typeof obj.enabled === "boolean") config.enabled = obj.enabled;
    else warn(filePath, "enabled must be a boolean", onProblem);
  }
  if (obj.data_dir !== undefined) {
    if (typeof obj.data_dir === "string") config.dataDir = obj.data_dir;
    else warn(filePath, "data_dir must be a string", onProblem);
  }
  if (obj.model_cache_dir !== undefined) {
    if (typeof obj.model_cache_dir === "string")
      config.modelCacheDir = obj.model_cache_dir;
    else warn(filePath, "model_cache_dir must be a string", onProblem);
  }
  if (obj.embed_dims !== undefined) {
    if (
      typeof obj.embed_dims === "number" &&

    Number.isFinite(obj.embed_dims) &&
    obj.embed_dims > 0
  ) {
    config.embedDims = obj.embed_dims;
  } else {
    warn(filePath, "embed_dims must be a positive number", onProblem);
  }
}
if (obj.heavy_mode !== undefined) {
  if (typeof obj.heavy_mode === "boolean") config.heavyMode = obj.heavy_mode;
  else warn(filePath, "heavy_mode must be a boolean", onProblem);
}

if (obj.exclude !== undefined) {
  if (
    Array.isArray(obj.exclude) &&
    obj.exclude.every((p) => typeof p === "string")
  ) {
    config.exclude = obj.exclude as string[];
  } else {
    warn(filePath, "exclude must be a list of strings", onProblem);
  }
}
if (obj.shared_worker !== undefined) {
  if (typeof obj.shared_worker === "boolean") config.sharedWorker = obj.shared_worker;
  else warn(filePath, "shared_worker must be a boolean", onProblem);
}
if (obj.reranker !== undefined) {
  if (typeof obj.reranker === "boolean") config.reranker = obj.reranker;
  else warn(filePath, "reranker must be a boolean", onProblem);
}
if (obj.file_summaries !== undefined) {
  if (typeof obj.file_summaries === "boolean") config.fileSummaries = obj.file_summaries;
  else warn(filePath, "file_summaries must be a boolean", onProblem);
}
if (obj.summary_llm === false) {
  config.summaryLlm = false;
} else if (obj.summary_llm !== undefined) {
  const llm = obj.summary_llm as Record<string, unknown> | null;

  const isText = (v: unknown): v is string => typeof v === "string" && v.trim().length > 0;
  if (llm && typeof llm === "object" && isText(llm.base_url) && isText(llm.model)) {
    config.summaryLlm = { baseUrl: llm.base_url.trim(), model: llm.model.trim() };
    if (isText(llm.api_key_env)) config.summaryLlm.apiKeyEnv = llm.api_key_env.trim();
    if (llm.api_key !== undefined)
      warn(
        filePath,
        "summary_llm.api_key is not supported (keys must not live in a committed file); put the key in an environment variable and name it with api_key_env",
        onProblem,
      );
    if (typeof llm.timeout_ms === "number" && Number.isInteger(llm.timeout_ms) && llm.timeout_ms > 0)
      config.summaryLlm.timeoutMs = llm.timeout_ms;
  } else {
    warn(filePath, "summary_llm needs non-empty base_url and model", onProblem);
  }
}
for (const [yamlKey, field] of [
  ["reindex_chunks", "reindexChunks"],
  ["reindex_summaries", "reindexSummaries"],
] as const) {
  if (obj[yamlKey] === undefined) continue;
  if (typeof obj[yamlKey] === "boolean") config[field] = obj[yamlKey];
  else warn(filePath, `${yamlKey} must be a boolean`, onProblem);
}
if (obj.agent_hint !== undefined) {
  if (typeof obj.agent_hint === "boolean") config.agentHint = obj.agent_hint;
  else warn(filePath, "agent_hint must be a boolean", onProblem);
}
for (const [yamlKey, field] of [
  ["tool_log", "toolLog"],
  ["tool_log_full_responses", "toolLogFullResponses"],

  ] as const) {
    if (obj[yamlKey] === undefined) continue;
    if (typeof obj[yamlKey] === "boolean") config[field] = obj[yamlKey];
    else warn(filePath, `${yamlKey} must be a boolean`, onProblem);
  }
  if (obj.install_skills !== undefined) {
    if (typeof obj.install_skills === "boolean")
      config.installSkills = obj.install_skills;
    else warn(filePath, "install_skills must be a boolean", onProblem);
  }
  if (obj.os_notifications !== undefined) {
    if (typeof obj.os_notifications === "boolean")
      config.osNotifications = obj.os_notifications;
    else warn(filePath, "os_notifications must be a boolean", onProblem);
  }

  const limits = [
    ["max_memory_mb", "maxMemoryMb"],
    ["embed_threads", "embedThreads"],
    ["embed_concurrency", "embedConcurrency"],
    ["embed_max_tokens", "embedMaxTokens"],
    ["max_file_bytes", "maxFileBytes"],
  ] as const;
  for (const [yamlKey, field] of limits) {
    const value = obj[yamlKey];
    if (value === undefined) continue;
    if (typeof value === "number" && Number.isInteger(value) && value > 0)
      config[field] = value;
    else warn(filePath, `${yamlKey} must be a positive integer`, onProblem);
  }

  return config;
}

export interface SummaryLlmConfig {
  /** e.g. `http://localhost:1234/v1`; `/chat/completions` is appended. */
  baseUrl: string;
  /** Exact model identifier as the server knows it. */
  model: string;
  /** Name of the environment variable holding the API key; the key itself never lives in the file. */
  apiKeyEnv?: string;
  timeoutMs?: number;
}

/** Environment variable read for the summary LLM's API key unless `api_key_env` names another. */
export const DEFAULT_SUMMARY_LLM_API_KEY_ENV = "AI_CONTEXT_SUMMARY_LLM_API_KEY";

/** Used when `summary_llm` is absent; a local oMLX server. Unreachable servers fall back to deterministic summaries. */
export const DEFAULT_SUMMARY_LLM: SummaryLlmConfig = {
  baseUrl: "http://127.0.0.1:8000/v1",
  model: "Qwen2.5-Coder-3B-Instruct-MLX-4bit",
  apiKeyEnv: DEFAULT_SUMMARY_LLM_API_KEY_ENV,
};

export interface AiContextConfigFile {
  /**
   * Master switch for this repository; absent means off. While off the plugin only provides
   * this file and does nothing else. `AI_CONTEXT_PLUGIN_ENABLED` overrides it.
   */
  enabled?: boolean;
  /** AI_CONTEXT_PLUGIN_DATA_DIR equivalent -- see project-key.ts. */
  dataDir?: string;
  /** AI_CONTEXT_PLUGIN_MODEL_CACHE_DIR equivalent -- see model-runtime.ts. */
  modelCacheDir?: string;
  /** AI_CONTEXT_PLUGIN_EMBED_DIMS equivalent -- see model-runtime.ts. */
  embedDims?: number;
  /** AI_CONTEXT_PLUGIN_HEAVY_MODE equivalent -- see heavy-mode.ts. */
  heavyMode?: boolean;
  /** Soft RSS budget of the host process while indexing, in MiB -- see memory-guard.ts. */
  maxMemoryMb?: number;
  /** Threads used by onnxruntime for embedding (lower = less CPU/fan, slower indexing). */
  embedThreads?: number;
  /** Files embedded in parallel (also the worker's inference slots); default 3. */
  embedConcurrency?: number;
  /** Hard cap on tokens per embedded text; attention memory is quadratic in it -- see embedder.ts. */
  embedMaxTokens?: number;
  /** Extra paths never indexed, gitignore syntax (e.g. `legacy/`, `*.generated.ts`). */
  exclude?: string[];
  /** Install the bundled `index-status` skill into <worktree>/.opencode/skills. Default on. */
  installSkills?: boolean;
  /** Append a short usage hint for the context tools to the agent's system prompt. Default on. */
  agentHint?: boolean;

  /** Write every tool call (tool, arguments, response summary) to `.opencode/ai-context/tool.log.md`. Default off. */
  toolLog?: boolean;
  /** With `toolLog`: log complete arguments and responses without truncation (default: arguments cut at 200 chars, response only summarized). Default off. */
  toolLogFullResponses?: boolean;
  /** Re-rank search candidates with a cross-encoder model (small ONNX model, runs in the shared worker). Default on. */
  reranker?: boolean;
  /** Index one summary chunk per multi-chunk file (deterministic, or LLM-written with `summaryLlm`). Default on. */
  fileSummaries?: boolean;
  /** Optional LLM that writes the file summaries; deterministic summaries are used when absent or failing. */
  summaryLlm?: SummaryLlmConfig | false;
  /** One-off: re-chunk and re-embed every file on the next start, then the plugin resets the flag to false. */
  reindexChunks?: boolean;
  /** One-off: rewrite every file summary on the next start (both flags = full re-index); reset afterwards. */
  reindexSummaries?: boolean;
  /** Run the embedding model in one shared background process instead of inside opencode. Default on. */
  sharedWorker?: boolean;
  /** Native OS popups for indexing start/finish/failure and plugin load. Default on. */
  osNotifications?: boolean;
  /** Files larger than this are skipped (typically generated/minified/bundled). */
  maxFileBytes?: number;
}

export function ensureConfigFile(
  worktree: string,
  onError?: (error: unknown) => void,
): boolean {
  try {
    if (!fs.existsSync(worktree)) return false;
    const filePath = resolveConfigFilePath(worktree);
    if (fs.existsSync(filePath)) return false;
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, CONFIG_TEMPLATE, { flag: "wx" });
    return true;
  } catch (error) {
    onError?.(error);
    return false;
  }
}

/**
 * Switches `reindex_chunks: true` / `reindex_summaries: true` back to false in place (comments and
 * other lines stay). Never throws; returns true when the file was changed.
 */

export function resetReindexFlags(
  worktree: string,
  onError?: (error: unknown) => void,
): boolean {
  try {
    const filePath = resolveConfigFilePath(worktree);
    if (!fs.existsSync(filePath)) return false;
    const content = fs.readFileSync(filePath, "utf8");
    const updated = content.replace(
      /^(\s*reindex_(?:chunks|summaries)\s*:\s*)true\b/gim,
      (_match, prefix: string) => `${prefix}false`,
    );
    if (updated === content) return false;
    fs.writeFileSync(filePath, updated);
    return true;
  } catch (error) {
    onError?.(error);
    return false;
  }
}

import fs from "node:fs";
import path from "node:path";

/** Volatile runtime files of the plugin; the backup under ai-context/backup stays committable. */
export const PLUGIN_GITIGNORE_ENTRIES = [
  "ai-context/index-status.json",
  "ai-context/index-status.json.*.tmp",
  "ai-context/index-tree.md",
  "ai-context/*.log.md", // error.log.md, tool.log.md and its rotated tool.<time>.log.md
];

/**
 * Makes sure `.opencode/.gitignore` ignores the status file. Creates the file
 * or appends missing entries; existing lines are kept. Never throws.
 * Returns true if the file was changed.
 */

export function ensurePluginGitignore(
  worktree: string,
  onError?: (error: unknown) => void,
): boolean {
  try {
    if (!fs.existsSync(worktree)) return false;
    const filePath = path.join(worktree, ".opencode", ".gitignore");
    const existing = fs.existsSync(filePath)
      ? fs.readFileSync(filePath, "utf8")
      : "";
    const present = new Set(existing.split("\n").map((l) => l.trim()));
    const missing = PLUGIN_GITIGNORE_ENTRIES.filter((e) => !present.has(e));
    if (missing.length === 0) return false;
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    const prefix =
      existing === "" || existing.endsWith("\n") ? existing : `${existing}\n`;
    fs.writeFileSync(filePath, `${prefix}${missing.join("\n")}\n`);
    return true;
  } catch (error) {
    onError?.(error);
    return false;
  }
}

export function isHeavyModeEnabled(
  env: Record<string, string | undefined> = process.env,
  heavyModeFromConfigFile?: boolean,
): boolean {
  const raw = env.AI_CONTEXT_PLUGIN_HEAVY_MODE;
  if (raw !== undefined) {
    return raw.toLowerCase() === "1" || raw.toLowerCase() === "true";
  }
  return heavyModeFromConfigFile === true;
}

export function truncateMatryoshka(vector: number[], dims: number): number[] {
  if (dims >= vector.length) return vector;
  return l2Normalize(vector.slice(0, dims));
}

export function createEmbedder(options: EmbedderOptions): Embedder {
  return {
    async embed(text, { prefix }) {
      const prefixedText = `${prefix}: ${text}`;
      const tokenized = await options.tokenize(prefixedText);
      const { inputIds, attentionMask } = capSequence(
        tokenized.inputIds,
        tokenized.attentionMask,
        options.maxTokens ?? DEFAULT_MAX_EMBED_TOKENS,
      );
      const { lastHiddenState } = await options.runInference(inputIds, attentionMask);
      const pooled = meanPool(lastHiddenState, attentionMask);
      const normalized = l2Normalize(pooled);
      return options.outputDims !== undefined
        ? truncateMatryoshka(normalized, options.outputDims)
        : normalized;
    },
  };
}

export interface TokenizeResult {
  inputIds: number[];
  attentionMask: number[];
}

export interface InferenceResult {
  /** `last_hidden_state`, shape [sequenceLength][hiddenSize]. */
  lastHiddenState: number[][];
}

export interface EmbedOptions {
  /**
   * nomic-embed-text-v1.5 requires a task-instruction prefix prepended
   * to the raw text -- "search_document: " for indexed chunks,
   * "search_query: " for the user's search query -- per its model
   * card. Embedding without one is a valid ONNX call but produces
   * embeddings that don't match the model's trained distribution.
   */
  prefix: EmbeddingPrefix;
}

export interface EmbedderOptions {
  tokenize(text: string): Promise<TokenizeResult>;
  runInference(inputIds: number[], attentionMask: number[]): Promise<InferenceResult>;
  /** Matryoshka truncation target; omitted/undefined keeps the model's full output dims. */
  outputDims?: number;
  /**
   * Hard cap on the sequence length passed to inference. Attention memory
   * is quadratic in it (~4.5 GB at 4096 tokens), so this is what bounds
   * memory per embedding. Defaults to DEFAULT_MAX_EMBED_TOKENS.
   */
  maxTokens?: number;
}

export const DEFAULT_MAX_EMBED_TOKENS = 512;

/** Truncates to `maxTokens`, keeping the trailing [SEP] token the tokenizer appended. */

function capSequence(ids: number[], mask: number[], maxTokens: number): TokenizeResult {
  if (ids.length <= maxTokens) return { inputIds: ids, attentionMask: mask };
  return {
    inputIds: [...ids.slice(0, maxTokens - 1), ids[ids.length - 1]!],
    attentionMask: [...mask.slice(0, maxTokens - 1), mask[mask.length - 1]!],
  };
}

export interface Embedder {
  embed(text: string, options: EmbedOptions): Promise<number[]>;
}

/** Attention-mask-weighted mean pooling over `last_hidden_state`. */

export function meanPool(lastHiddenState: number[][], attentionMask: number[]): number[] {
  const hiddenSize = lastHiddenState[0]?.length ?? 0;
  const sum = new Array<number>(hiddenSize).fill(0);
  let attendedCount = 0;
  for (let t = 0; t < lastHiddenState.length; t++) {
    if (attentionMask[t] !== 1) continue;
    attendedCount++;
    const tokenVector = lastHiddenState[t]!;
    for (let d = 0; d < hiddenSize; d++) {
      sum[d]! += tokenVector[d]!;
    }
  }
  if (attendedCount === 0) return sum;
  return sum.map((value) => value / attendedCount);
}

export function l2Normalize(vector: number[]): number[] {
  let normSquared = 0;
  for (const value of vector) normSquared += value * value;
  if (normSquared === 0) return vector.slice();
  const norm = Math.sqrt(normSquared);
  return vector.map((value) => value / norm);
}

/**
 * Matryoshka dimension truncation: keep only the first `dims` values
 * (nomic's Matryoshka training orders dimensions by importance, so a
 * prefix slice -- not an arbitrary subset -- is the valid truncation)
 * and re-normalize, since the shorter slice of a unit vector is no
 * longer unit length itself.
 */

export function resolveOutputDims(options: OutputDimsOptions = {}): number | undefined {
  if (options.dims !== undefined) return options.dims;
  const env = options.env ?? process.env;
  const raw = env.AI_CONTEXT_PLUGIN_EMBED_DIMS;
  if (raw !== undefined) {
    const parsed = Number(raw);
    if (Number.isFinite(parsed) && parsed > 0) return parsed;
  }
  return options.fileDims;
}

/**
 * Splits a flat row-major `[1, seqLen, hidden]` ONNX output buffer into
 * `seqLen` rows of length `hidden` -- pure, so it's unit-testable
 * without a real ONNX session. Ignores the batch dimension (always 1:
 * this plugin embeds one text at a time, no batching yet).
 */

export function reshapeHiddenState(
  flatData: Float32Array | number[],
  dims: readonly number[],
): number[][] {
  const [, seqLen, hidden] = dims;
  const rows: number[][] = [];
  for (let t = 0; t < (seqLen ?? 0); t++) {
    const row: number[] = [];
    for (let d = 0; d < (hidden ?? 0); d++) {
      row.push(Number(flatData[t * (hidden ?? 0) + d]));
    }
    rows.push(row);
  }
  return rows;
}

/** Real `ensureModelFiles`: downloads (or reuses the cached copy of) the tokenizer + quantized ONNX model. */

export async function defaultEnsureModelFiles(options: ModelCacheDirOptions = {}): Promise<ModelFiles> {
  const { downloadFileToCacheDir } = await import("@huggingface/hub");
  const cacheDir = resolveModelCacheDir(options);
  const repo = { name: MODEL_REPO, type: "model" as const };
  const [tokenizerPath, modelPath] = await Promise.all([
    downloadFileToCacheDir({ repo, path: TOKENIZER_FILE, cacheDir }),
    downloadFileToCacheDir({ repo, path: MODEL_FILE, cacheDir }),
  ]);
  return { tokenizerPath, modelPath };
}

/** Real `loadTokenizer`: wraps `tokenizers`' `Tokenizer.fromFile` (adds CLS/SEP automatically, per the BERT-style tokenizer config nomic publishes). */

export async function defaultLoadTokenizer(tokenizerPath: string): Promise<TokenizerHandle> {
  const { Tokenizer } = await import("tokenizers");
  const tokenizer = Tokenizer.fromFile(tokenizerPath);
  return {
    async tokenize(text) {
      const encoding = await tokenizer.encode(text);
      return { inputIds: encoding.getIds(), attentionMask: encoding.getAttentionMask() };
    },
  };
}

export const DEFAULT_EMBED_THREADS = 6;

/**
 * Session options that favor a small, predictable footprint over raw
 * speed: no CPU memory arena (it retains the peak of the largest input
 * for the process lifetime), no memory-pattern pre-planning, and few
 * threads (indexing is background work and must not saturate the CPU).
 */

export function buildSessionOptions(options: { threads?: number }) {
  return {
    enableCpuMemArena: false,
    enableMemPattern: false,
    executionMode: "sequential" as const,
    intraOpNumThreads: options.threads ?? DEFAULT_EMBED_THREADS,
    interOpNumThreads: 1,
  };
}

/** Real `createSession`: wraps `onnxruntime-node`'s `InferenceSession`. */

export async function defaultCreateSession(modelPath: string, options: { threads?: number } = {}): Promise<SessionHandle> {
  const ort = await import("onnxruntime-node");
  const session = await ort.InferenceSession.create(modelPath, buildSessionOptions(options));
  return {
    async runInference(inputIds, attentionMask) {
      const n = inputIds.length;
      const toInt64Tensor = (values: number[]) =>
        new ort.Tensor("int64", BigInt64Array.from(values.map(BigInt)), [1, n]);
      const results = await session.run({
        input_ids: toInt64Tensor(inputIds),
        token_type_ids: toInt64Tensor(new Array(n).fill(0)),
        attention_mask: toInt64Tensor(attentionMask),
      });
      const output = results["last_hidden_state"]!;
      return { lastHiddenState: reshapeHiddenState(output.data as Float32Array, output.dims) };
    },
  };
}

/**
 * Lazily downloads/loads the model runtime on the FIRST embed call
 * (not at plugin startup -- avoids a network round trip/model load on
 * every OpenCode session start when semantic_search may never be
 * called), memoizing the init promise so concurrent/later calls reuse
 * the same tokenizer + ONNX session instead of reloading them. A failed
 * init is NOT cached, so a transient failure (e.g. no network on first
 * use) can be retried on the next call rather than permanently
 * breaking semantic_search for the rest of the session.
 *
 * Returns BOTH `embedQuery` (for search queries, "search_query: "

export interface LazyEmbedder {
  embedQuery(text: string): Promise<number[]>;
  embedDocument(text: string): Promise<number[]>;
}

export function createLazyEmbedder(deps: ModelRuntimeDeps): LazyEmbedder {
  let initPromise: Promise<{ tokenize: TokenizerHandle["tokenize"]; runInference: SessionHandle["runInference"] }> | null = null;

  async function init() {
    const { tokenizerPath, modelPath } = await deps.ensureModelFiles();
    const [tokenizer, session] = await Promise.all([
      deps.loadTokenizer(tokenizerPath),
      deps.createSession(modelPath),
    ]);
    return { tokenize: tokenizer.tokenize, runInference: session.runInference };
  }

  async function embed(text: string, prefix: "search_query" | "search_document"): Promise<number[]> {
    if (!initPromise) {
      deps.onModelLoading?.(true);
      initPromise = init()
        .catch((error) => {
          initPromise = null; // don't cache a failed init -- allow retry on the next call
          deps.onModelError?.(error);
          throw error;
        })
        .finally(() => deps.onModelLoading?.(false));
    }
    const { tokenize, runInference } = await initPromise;
    const embedder = createEmbedder({ tokenize, runInference, outputDims: deps.outputDims, maxTokens: deps.maxTokens });
    return embedder.embed(text, { prefix });
  }

  return {
    embedQuery: (text) => embed(text, "search_query"),
    embedDocument: (text) => embed(text, "search_document"),
  };
}

/** Real default, wiring all pieces above together -- used by plugin.ts. */

 * is always all-zeros for our single-sequence (no sentence-pair) use.
 */

