export function buildEmbedInput(parts: EmbedInputParts): string {
  const header = [`File: ${parts.relativePath}`];
  if (parts.symbol) header.push(`Symbol: ${parts.symbol}`);
  return `${header.join("\n")}\n\n${parts.text}`;
}

export function createIgnoreMatcher(
  gitignoreContent: string | null,
): IgnoreMatcher {
  if (gitignoreContent === null) {
    return { isIgnored: () => false };
  }
  const ig = ignore().add(gitignoreContent);
  return {
    isIgnored: (relativePath: string) => ig.ignores(relativePath),
  };
}

/** Reads `<worktree>/.gitignore`, or returns `null` if it doesn't exist. */

export function loadGitignoreSync(worktree: string): string | null {
  const filePath = path.join(worktree, ".gitignore");
  if (!fs.existsSync(filePath)) return null;
  return fs.readFileSync(filePath, "utf8");
}

/**
 * Combines both checks into the single predicate the indexing pipeline
 * actually needs: `true` means "index this file", mirroring the
 * original's "include_extensions AND NOT gitignored" combination.
 */

export function createFileFilter(
  worktree: string,
  options: { exclude?: string[] } = {},
): (relativePath: string) => boolean {
  const matcher = createIgnoreMatcher(loadGitignoreSync(worktree));
  const excluded = createExcludeMatcher(options.exclude);
  return (relativePath: string) =>
    !isPluginMetadata(relativePath) &&
    isIndexableExtension(relativePath) &&
    !matcher.isIgnored(relativePath) &&
    !excluded.isIgnored(relativePath);
}

/** Matcher for the config file's `exclude` list (gitignore syntax); empty list ignores nothing. */

export function createExcludeMatcher(
  patterns: string[] | undefined,
): IgnoreMatcher {
  if (!patterns || patterns.length === 0) return { isIgnored: () => false };
  return createIgnoreMatcher(patterns.join("\n"));
}

export function isIndexableExtension(relativePath: string): boolean {
  const base = path.basename(relativePath);
  if (INDEXABLE_FILENAMES.has(base)) return true;
  const ext = path.extname(relativePath).toLowerCase();
  return ext !== "" && INDEXABLE_EXTENSIONS.has(ext);
}

const PLUGIN_METADATA_PREFIXES = [
  ".opencode/ai-context/",
  ".opencode/skills/index-status/",
];

/**
 * This plugin's own bookkeeping (backup export, allow-list, index-status.json).
 * Never indexable: index-status.json is rewritten while indexing, so indexing
 * it would feed back into `file.watcher.updated`.
 */

export function isPluginMetadata(relativePath: string): boolean {
  const normalized = relativePath.replace(/\\/g, "/");
  return PLUGIN_METADATA_PREFIXES.some((prefix) =>
    normalized.startsWith(prefix),
  );
}

export interface IgnoreMatcher {
  isIgnored(relativePath: string): boolean;
}

/**
 * Builds a gitignore-pattern matcher from raw `.gitignore` file content
 * (or `null`, meaning nothing is ignored). Content is injected rather
 * than read here so this stays unit-testable without real fs I/O --
 * see `loadGitignoreSync` for the real loader.
 */

export function createLlmSummarizer(options: LlmSummarizerOptions): LlmSummarize {
  const url = `${options.baseUrl.replace(/\/+$/, "")}/chat/completions`;
  const doFetch = options.fetch ?? fetch;
  // `tool_choice: "none"` keeps servers that inject global MCP tools from doing so.
  // Strict OpenAI rejects it without `tools` (HTTP 400): then retry once without and remember.
  let sendToolChoice = true;
  return async ({ relativePath, content }) => {
    const headers: Record<string, string> = { "content-type": "application/json" };
    if (options.apiKey) headers.authorization = `Bearer ${options.apiKey}`;
    const post = () =>
      doFetch(url, {
        method: "POST",
        headers,
        signal: AbortSignal.timeout(options.timeoutMs ?? 60_000),
        body: JSON.stringify({
          model: options.model,
          temperature: 0,
          max_tokens: 200,
          ...(sendToolChoice ? { tool_choice: "none" } : {}),
          messages: [
            {
              role: "system",
              content: options.systemPrompt ?? FILE_SYSTEM_PROMPT,
            },
            {
              role: "user",
              content: `${relativePath ? `File: ${relativePath}\n\n` : ""}${content.slice(0, MAX_LLM_CONTENT_CHARS)}`,
            },
          ],
        }),
      });
    let response = await post();
    if (response.status === 400 && sendToolChoice) {
      sendToolChoice = false;
      response = await post();
    }
    if (response.status === 401)
      throw new SummaryLlmAuthError(

        authMessage(options.apiKeyEnvName ?? DEFAULT_SUMMARY_LLM_API_KEY_ENV, !!options.apiKey),
      );
    if (!response.ok) throw new Error(`summary LLM answered HTTP ${response.status}`);
    const json = (await response.json()) as { choices?: { message?: { content?: string } }[] };
    const text = json.choices?.[0]?.message?.content?.trim();
    if (!text) throw new Error("summary LLM returned an empty answer");
    if (looksLikeToolCall(text))
      throw new Error("summary LLM answered with a tool call instead of a summary (server injects tools?)");
    return text;
  };
}

export interface SummaryInput {
  relativePath: string;
  language: string;
  symbols: (string | undefined)[];
  content: string;
}

/** A summary that is only the deterministic fallback although an LLM was asked for. */

export interface SummaryProviderOptions {
  llm?: LlmSummarize;
  onProblem?: (error: unknown) => void;
}

/** Resolves to a plain string, or a `FallbackSummary` when an LLM is configured but did not deliver. */

export function createSummaryProvider(
  options: SummaryProviderOptions,
): (input: SummaryInput) => Promise<string | FallbackSummary> {
  let failures = 0;
  return async (input) => {
    if (options.llm && failures < MAX_FAILURES) {
      try {
        const text = await options.llm({ relativePath: input.relativePath, content: input.content });
        failures = 0;
        return text;
      } catch (error) {
        failures++;
        options.onProblem?.(error);
      }
    }
    const text = buildDeterministicSummary(input);
    return options.llm ? { text, fallback: true } : text;
  };
}

export interface DocSummaryProviderOptions {
  llm?: LlmSummarize;
  onProblem?: (error: unknown) => void;
}

/** Summarizer for doc-tree nodes and whole documents; null (no summary) when the LLM is absent or failing. */

export function createDocSummaryProvider(
  options: DocSummaryProviderOptions,
): (text: string, kind: "node" | "document") => Promise<string | null> {
  let failures = 0;
  return async (text) => {
    if (!options.llm || failures >= MAX_FAILURES) return null;
    try {
      const summary = await options.llm({ relativePath: "", content: text });
      failures = 0;
      return summary;
    } catch (error) {
      failures++;
      options.onProblem?.(error);
      return null;
    }
  };
}

export interface FallbackSummary {
  text: string;
  fallback: boolean;
}

export type LlmSummarize = (input: { relativePath: string; content: string }) => Promise<string>;

const MAX_SYMBOLS = 40;
const MAX_LLM_CONTENT_CHARS = 12_000;
const MAX_FAILURES = 3;

const FILE_SYSTEM_PROMPT =
  "You summarize source files for a code search index. Answer in 2-3 plain sentences: the file's purpose, its main responsibilities and key names. No markdown, no preamble.";

export const DOC_SYSTEM_PROMPT =
  "You summarize documentation for a search index. Answer in 1-2 plain sentences: what the text covers and the key terms, decisions or names it mentions. No markdown, no preamble.";

function leadingComment(content: string): string | undefined {
  const lines = content.split("\n").slice(0, 40);
  const picked: string[] = [];
  for (const raw of lines) {
    const line = raw.trim();
    if (picked.length === 0 && (line === "" || line === "/**" || line === "/*" || line.startsWith("#!"))) continue;
    const m = /^(?:\/\/+|\/?\*+\/?|#+|--|""")\s?(.*)$/.exec(line);
    if (!m) break;
    const text = m[1]!.replace(/\*\/$/, "").trim();
    if (text) picked.push(text);
    if (picked.length >= 3) break;
  }
  return picked.length > 0 ? picked.join(" ") : undefined;
}

export function buildDeterministicSummary(input: SummaryInput): string {
  const symbols = [...new Set(input.symbols.filter((s): s is string => !!s))].slice(0, MAX_SYMBOLS);
  const parts = [`File ${input.relativePath} (${input.language}).`];
  const comment = leadingComment(input.content);
  if (comment) parts.push(comment);
  if (symbols.length > 0) parts.push(`Defines: ${symbols.join(", ")}.`);
  return parts.join(" ");
}

/** The provider answered HTTP 401; the message tells the user how to fix it. */

export class SummaryLlmAuthError extends Error {
  override name = "SummaryLlmAuthError";
}

function authMessage(envName: string, keyWasSent: boolean): string {
  const fix = `Set it with: export ${envName}=<your key>  and restart opencode.`;
  return keyWasSent
    ? `Summary LLM answered 401: the API key in ${envName} was rejected. ${fix}`
    : `Summary LLM answered 401: API key not set. ${fix}`;
}

export interface LlmSummarizerOptions {
  baseUrl: string;
  model: string;
  apiKey?: string;
  /** Variable the user is told to set on HTTP 401. */
  apiKeyEnvName?: string;
  timeoutMs?: number;
  /** Replaces the code-oriented default prompt, e.g. for documentation. */
  systemPrompt?: string;
  fetch?: typeof fetch;
}

/**
 * True when a "summary" is really a tool call. Some OpenAI-compatible servers
 * (oMLX with a global MCP config) inject their tool list into every request, and
 * small models then answer with a JSON tool call instead of prose.
 */

export function looksLikeToolCall(text: string): boolean {
  if (/\b[A-Za-z0-9-]+__[A-Za-z0-9_-]+\b/.test(text) && /"(?:name|arguments)"\s*:/.test(text)) return true;
  const body = text
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/```\s*$/, "")
    .trim();
  return /^\{\s*"name"\s*:/.test(body) && /"arguments"\s*:/.test(body);
}

import type { Node } from "web-tree-sitter";
import { withParsedTree } from "./parse.js";
import type { LanguageSpec } from "./language-specs.js";
import { symbolsFromTree } from "./symbol-extractor.js";
import type { GraphSymbol } from "../../storage/graph-store.js";

/** A call site as written in source, before being matched against known symbols. */

switch (node.type) {
    case "call_expression": {
      if (language === "kotlin") return kotlinCallee(node);
      const fn = node.childForFieldName("function");
      if (fn?.type === "super" || fn?.type === "import") return null;
      if (fn?.type === "identifier" && fn.text === "require" && (language === "javascript" || language === "typescript")) return null;
      return calleeFromFunction(fn, language);
    }

case "call": {
      if (language === "ruby") {
        const method = node.childForFieldName("method")?.text;
        const receiver = node.childForFieldName("receiver");
        if (!method || (!receiver && RUBY_REQUIRES.has(method))) return null;
        return { calleeName: method, qualifier: qualifierOf(receiver) };
      }
      return calleeFromFunction(node.childForFieldName("function"), language);
    }

case "method_invocation": {
      const name = node.childForFieldName("name");
      return name ? { calleeName: name.text, qualifier: qualifierOf(node.childForFieldName("object")) } : null;
    }

case "object_creation_expression": {
      const target = node.childForFieldName("constructor") ?? node.childForFieldName("type");
      const calleeName = typeName(target);
      return calleeName ? { calleeName, kind: "new" } : null;
    }
    default:
      return null;
  }
}

export function innermostCaller(symbols: GraphSymbol[], line: number): string | undefined {
  let best: GraphSymbol | undefined;
  for (const s of symbols) {
    if (!CALLER_KINDS.has(s.kind) || line < s.startLine || line > s.endLine) continue;
    if (!best || s.endLine - s.startLine < best.endLine - best.startLine || (s.endLine - s.startLine === best.endLine - best.startLine && s.startLine > best.startLine)) {
      best = s;
    }
  }
  return best?.name;
}

export function callsFromTree(root: Node, spec: LanguageSpec, symbols: GraphSymbol[]): RawCall[] {
  const out: RawCall[] = [];
  const visit = (n: Node): void => {
    const ref = describeCall(n, spec.language);
    if (ref) {
      const line = n.startPosition.row + 1;
      out.push({ callerSymbol: innermostCaller(symbols, line), ...ref, line });
    }
    for (const c of n.namedChildren) visit(c);
  };
  visit(root);
  return out;
}

/** Raw calls of `content`, or `null` for unsupported extensions / parse failures. */

export function extractCalls(content: string, extension: string): Promise<RawCall[] | null> {
  return withParsedTree(content, extension, (root, spec) => callsFromTree(root, spec, symbolsFromTree(root, spec)));
}

interface CalleeRef {
  calleeName: string;
  qualifier?: string;
  kind?: string;
}

const CALLER_KINDS = new Set(["function", "method", "constructor"]);

/** Receivers like `a().d` or `x[0]` can't be matched to a type by name, so they carry no qualifier. */

function qualifierOf(node: Node | null | undefined): string | undefined {
  if (!node) return undefined;
  const text = node.text.replace(/\s+/g, "");
  return /^[\w$.:@?!]+$/.test(text) ? text.replace(/[?!]/g, "") : undefined;
}

function typeName(node: Node | null | undefined): string | undefined {
  if (!node) return undefined;
  const text = node.text.replace(/<.*$/s, "").split(/[.:]+/).filter(Boolean);
  return text[text.length - 1];
}

function scopedName(node: Node): CalleeRef | null {
  const parts = node.text.replace(/<[^<>]*>/g, "").replace(/\s+/g, "").split("::").filter(Boolean);
  const calleeName = parts[parts.length - 1];
  if (!calleeName) return null;
  return { calleeName, qualifier: parts.length > 1 ? parts.slice(0, -1).join("::") : undefined };
}

function member(receiver: Node | null, name: Node | null): CalleeRef | null {
  const calleeName = name?.type === "generic_name" ? name.namedChildren[0]?.text : name?.text;
  return calleeName ? { calleeName, qualifier: qualifierOf(receiver) } : null;
}

/** Callee behind an expression used as a function (handles generic wrappers). */

case "generic_name":
      return fn.namedChildren[0] ? { calleeName: fn.namedChildren[0].text } : null;
    default:
      return null;
  }
}

export interface RawCall {
  /** Innermost declared function/method/constructor containing the call; absent at module scope. */
  callerSymbol?: string;
  calleeName: string;
  /** Receiver or scope text (`obj`, `a.b`, `Foo`, `this`) when it is a plain identifier chain. */
  qualifier?: string;
  /** `new` for constructor calls. */
  kind?: string;
  line: number;
}

function kotlinCallee(node: Node): CalleeRef | null {
  const first = node.namedChildren[0];
  if (!first) return null;
  if (first.type === "identifier") return { calleeName: first.text };
  if (first.type === "navigation_expression") {
    const parts = first.namedChildren;
    const name = parts[parts.length - 1];
    return name ? { calleeName: name.text, qualifier: qualifierOf(parts[0]) } : null;
  }
  return null;
}

const RUBY_REQUIRES = new Set(["require", "require_relative", "load"]);

export interface CallCandidate {
  relativePath: string;
  name: string;
  kind: string;
  container?: string;
}

export interface CallSite {
  calleeName: string;
  qualifier?: string;
  /** `new` for constructors, `inject`/`decorator` for Angular type references, `jsx` for component tags. */
  kind?: string;
}

export interface CallResolutionContext {
  fromPath: string;
  /** Class/impl enclosing the caller; used for `this`/`self` calls. */
  callerContainer?: string;
  /** Every symbol named `calleeName` in the repo. */
  candidates: CallCandidate[];
  /** Files the caller's file imports (resolved). */
  importedFiles: ReadonlySet<string>;
}

export interface CallResolution {
  calleePath?: string;
  ambiguous: boolean;
  candidateCount?: number;
}

const CALLABLE_KINDS = new Set(["function", "method", "constructor", "macro"]);
const CLASS_LIKE_KINDS = new Set(["class", "struct", "record", "object"]);
const SELF_QUALIFIERS = new Set(["this", "self", "cls", "@"]);

const posix = path.posix;
const stemOf = (file: string) => file.slice(0, file.length - posix.extname(file).length);

function targetKey(c: CallCandidate, byPathOnly: boolean): string {
  return byPathOnly ? c.relativePath : `${c.relativePath}\u0000${c.container ?? ""}`;
}

function distinct(candidates: CallCandidate[], byPathOnly: boolean): CallCandidate[] {
  const seen = new Map<string, CallCandidate>();
  for (const c of candidates) if (!seen.has(targetKey(c, byPathOnly))) seen.set(targetKey(c, byPathOnly), c);
  return [...seen.values()];
}

export function resolveCall(call: CallSite, ctx: CallResolutionContext): CallResolution {
  const isNew = call.kind === "new";
  const isTypeRef = call.kind === "inject" || call.kind === "decorator";
  const named = ctx.candidates.filter((c) => c.name === call.calleeName && c.kind !== "selector");
  let pool = isNew || isTypeRef
    ? named.filter((c) => CLASS_LIKE_KINDS.has(c.kind) || c.kind === "constructor")
    : named.filter((c) => CALLABLE_KINDS.has(c.kind));
  if (pool.length === 0 && !isNew && !isTypeRef) pool = named.filter((c) => CLASS_LIKE_KINDS.has(c.kind));
  if (pool.length === 0 && isTypeRef) pool = named; // injection tokens, interfaces, constants
  pool = distinct(pool, isNew || isTypeRef);
  if (pool.length === 0) return { ambiguous: false };

  const narrow = (pred: (c: CallCandidate) => boolean): boolean => {
    const kept = pool.filter(pred);
    if (kept.length === 0) return false;
    pool = kept;
    return true;
  };
  const inImported = (c: CallCandidate) =>
    ctx.importedFiles.has(c.relativePath) ||
    [...ctx.importedFiles].some((f) => stemOf(f) === stemOf(c.relativePath)); // C header -> implementation pairing
  const sameDir = (c: CallCandidate) => posix.dirname(c.relativePath) === posix.dirname(ctx.fromPath);

  const qualifier = call.qualifier;
  const lastSegment = qualifier?.split(/[.:]+/).filter(Boolean).pop();
  let evidence = false;

  if (!qualifier) {
    evidence = narrow((c) => c.relativePath === ctx.fromPath) || narrow(inImported) || narrow(sameDir);

  } else if (SELF_QUALIFIERS.has(qualifier)) {
    evidence = narrow((c) => c.relativePath === ctx.fromPath);
    if (ctx.callerContainer && narrow((c) => c.container === ctx.callerContainer)) evidence = true;
  } else {
    evidence =
      narrow((c) => c.container === lastSegment) ||
      narrow((c) => stemOf(posix.basename(c.relativePath)) === lastSegment || posix.basename(posix.dirname(c.relativePath)) === lastSegment);
    // Import evidence only narrows a receiver of unknown type; it never makes the match certain.
    if (!evidence) narrow(inImported);
  }

  if (pool.length === 1) {
    return evidence
      ? { calleePath: pool[0]!.relativePath, ambiguous: false }
      : { calleePath: pool[0]!.relativePath, ambiguous: true, candidateCount: 1 };
  }
  return { ambiguous: true, candidateCount: pool.length };
}

import { withParsedTree } from "./parse.js";
import { symbolsFromTree } from "./symbol-extractor.js";
import { importsFromTree, type RawImport } from "./import-extractor.js";
import { frameworkFromTree } from "./framework-extractor.js";
import { callsFromTree, type RawCall } from "./call-extractor.js";
import type { GraphSymbol } from "../../storage/graph-store.js";

export function extractFileGraph(content: string, extension: string): Promise<ExtractedFileGraph | null> {
  return withParsedTree(content, extension, (root, spec) => {
    const symbols = symbolsFromTree(root, spec);
    const framework = frameworkFromTree(root, spec, symbols);
    return {
      language: spec.language,
      symbols: [...symbols, ...framework.symbols],
      imports: importsFromTree(root, spec),
      calls: [...callsFromTree(root, spec, symbols), ...framework.calls],
    };
  });
}

export interface ExtractedFileGraph {
  language: string;
  symbols: GraphSymbol[];
  imports: RawImport[];
  calls: RawCall[];
}

/** Symbols, imports and calls of one file from a single parse; `null` when unsupported or unparseable. */

function decoratorMetadata(args: Node | null, cls: Node, className: string, out: FrameworkGraph): void {
  const obj = args?.namedChildren[0];
  if (!obj || obj.type !== "object") return;
  const meta = pairs(obj);
  for (const [key, value] of meta) {
    if (key === "selector") {
      const selector = stringValue(value);
      if (selector) out.symbols.push(...selectorSymbols(selector, cls, className));
    } else if (key === "template") {
      const text = stringValue(value);
      if (text) out.calls.push(...templateEdges(text, line(value), className));
    } else if (METADATA_ARRAY_KEYS.has(key) && value.type === "array") {
      for (const el of value.namedChildren) {
        const targets = el.type === "object" ? [...pairs(el)].filter(([k]) => PROVIDER_KEYS.has(k)).map(([, v]) => v) : [el];
        for (const t of targets) {
          if (t.type === "identifier") out.calls.push({ callerSymbol: className, calleeName: t.text, kind: "decorator", line: line(t) });
        }
      }
    }
  }
}

function constructorInjections(cls: Node, className: string, out: FrameworkGraph): void {
  const body = cls.childForFieldName("body");
  const ctor = body?.namedChildren.find((m) => m.type === "method_definition" && m.childForFieldName("name")?.text === "constructor");
  const params = ctor?.childForFieldName("parameters");
  if (!params) return;
  for (const p of params.namedChildren) {
    if (p.type !== "required_parameter" && p.type !== "optional_parameter") continue;
    for (const d of p.namedChildren.filter((c) => c.type === "decorator")) {
      const info = decoratorName(d);
      const arg = info?.name === "Inject" ? info.args?.namedChildren[0] : undefined;
      if (arg?.type === "identifier") out.calls.push({ callerSymbol: className, calleeName: arg.text, kind: "inject", line: line(arg) });
    }
    const type = p.namedChildren.find((c) => c.type === "type_annotation");
    const name = typeNameOf(type);
    if (name) out.calls.push({ callerSymbol: className, calleeName: name, kind: "inject", line: line(type!) });
  }
}

function jsxEdge(node: Node, symbols: GraphSymbol[]): RawCall | null {
  const name = node.namedChildren[0];
  if (!name) return null;
  let calleeName: string | undefined;
  let qualifier: string | undefined;
  if (name.type === "identifier") {
    if (isUpper(name.text)) calleeName = name.text;
  } else if (name.type === "member_expression") {
    const prop = name.childForFieldName("property")?.text;
    const object = name.childForFieldName("object")?.text;
    if (prop && isUpper(prop) && object && /^[\w$.]+$/.test(object)) {
      calleeName = prop;
      qualifier = object;
    }
  }
  if (!calleeName) return null;
  return { callerSymbol: innermostCaller(symbols, line(node)), calleeName, qualifier, kind: "jsx", line: line(node) };
}

export function frameworkFromTree(root: Node, spec: LanguageSpec, symbols: GraphSymbol[]): FrameworkGraph {
  const out: FrameworkGraph = { symbols: [], calls: [] };
  if (spec.language !== "typescript" && spec.language !== "javascript") return out;

  const visit = (n: Node, enclosingClass: string | undefined): void => {
    let cls = enclosingClass;
    if (CLASS_NODES.has(n.type)) {
      const className = n.childForFieldName("name")?.text;
      if (className) {
        cls = className;
        const decorators = classDecorators(n).flatMap((d) => decoratorName(d) ?? []);
        if (decorators.some((d) => ANGULAR_DECORATORS.has(d.name))) {
          constructorInjections(n, className, out);
          for (const d of decorators) if (ANGULAR_DECORATORS.has(d.name)) decoratorMetadata(d.args, n, className, out);
        }
      }
    } else if (n.type === "jsx_opening_element" || n.type === "jsx_self_closing_element") {
      const edge = jsxEdge(n, symbols);
      if (edge) out.calls.push(edge);
    } else if (n.type === "call_expression") {
      const fn = n.childForFieldName("function");
      const arg = n.childForFieldName("arguments")?.namedChildren[0];
      if (fn?.type === "identifier" && fn.text === "inject" && arg?.type === "identifier") {
        out.calls.push({ callerSymbol: innermostCaller(symbols, line(n)) ?? enclosingClass, calleeName: arg.text, kind: "inject", line: line(n) });
      }
    }
    for (const c of n.namedChildren) visit(c, cls);
  };
  visit(root, undefined);
  return out;
}

export interface FrameworkGraph {
  symbols: GraphSymbol[];
  calls: RawCall[];
}

const CLASS_NODES = new Set(["class_declaration", "abstract_class_declaration", "class"]);
const ANGULAR_DECORATORS = new Set(["Component", "Directive", "Pipe", "NgModule", "Injectable"]);
const METADATA_ARRAY_KEYS = new Set(["imports", "declarations", "providers", "exports", "bootstrap", "viewProviders"]);
const PROVIDER_KEYS = new Set(["provide", "useClass", "useExisting"]);

const line = (n: Node) => n.startPosition.row + 1;
const isUpper = (s: string) => /^[A-Z]/.test(s);

function decoratorName(decorator: Node): { name: string; args: Node | null } | null {
  const first = decorator.namedChildren[0];
  if (!first) return null;
  if (first.type === "identifier") return { name: first.text, args: null };
  if (first.type !== "call_expression") return null;
  const fn = first.childForFieldName("function");
  return fn?.type === "identifier" ? { name: fn.text, args: first.childForFieldName("arguments") } : null;
}

/** Decorators of a class; for `export class` they are siblings inside the export statement. */

function classDecorators(cls: Node): Node[] {
  const own = cls.namedChildren.filter((c) => c.type === "decorator");
  const exported = cls.parent?.type === "export_statement" ? cls.parent.namedChildren.filter((c) => c.type === "decorator") : [];
  return [...exported, ...own];
}

function typeNameOf(annotation: Node | null | undefined): string | undefined {
  const t = annotation?.namedChildren[0];
  if (!t) return undefined;
  if (t.type === "type_identifier") return t.text;
  if (t.type === "generic_type") return t.namedChildren[0]?.type === "type_identifier" ? t.namedChildren[0].text : undefined;
