export interface MemoryGuard {
  ensure(): Promise<void>;
}

export interface MemoryGuardOptions {
  /** <= 0 disables the guard. */
  limitMb: number;
  getRss?: () => number;
  collect?: () => void;
  sleep?: (ms: number) => Promise<void>;
  retries?: number;
  pauseMs?: number;
}

export function createMemoryGuard(options: MemoryGuardOptions): MemoryGuard {
  const getRss = options.getRss ?? (() => process.memoryUsage().rss);
  const collect = options.collect ?? defaultCollect;
  const sleep =
    options.sleep ??
    ((ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms)));
  const retries = options.retries ?? 5;
  const pauseMs = options.pauseMs ?? 500;
  const limitBytes = options.limitMb * 1024 * 1024;

  return {
    async ensure() {
      if (options.limitMb <= 0 || getRss() <= limitBytes) return;
      for (let attempt = 0; attempt < retries; attempt++) {
        collect();
        await sleep(pauseMs);
        if (getRss() <= limitBytes) return;
      }
      throw new MemoryLimitError(
        Math.round(getRss() / (1024 * 1024)),
        options.limitMb,
      );
    },
  };
}

function defaultCollect(): void {
  const bun = (globalThis as { Bun?: { gc?: (force: boolean) => void } }).Bun;
  if (bun?.gc) bun.gc(true);
  else (globalThis as { gc?: () => void }).gc?.();
}

export class MemoryLimitError extends Error {
  constructor(
    readonly rssMb: number,
    readonly limitMb: number,
  ) {
    super(
      `indexing stopped: process memory is ${rssMb} MB, above max_memory_mb=${limitMb}. ` +
        `Raise max_memory_mb in .opencode/ai-context.config.yaml or lower embed_max_tokens / max_file_bytes.`,
    );
    this.name = "MemoryLimitError";
  }
}

interface MatchSite {
  lineIndex: number; // 0-based
  symbol: string | undefined;
}

/** `_chunk_by_pattern`'s port: merges every pattern's matches, sorts by position, and slices `lines` at each boundary. */

function chunkByPattern(lines: string[], patterns: RegExp[]): Chunk[] | null {
  const source = lines.join("\n");
  const matchStarts: number[] = [];
  const matchSymbols: (string | undefined)[] = [];

  for (const pattern of patterns) {
    const re = new RegExp(
      pattern.source,
      pattern.flags.includes("g") ? pattern.flags : pattern.flags + "g",
    );
    for (const m of source.matchAll(re)) {
      matchStarts.push(m.index!);
      matchSymbols.push(m[1]);
    }
  }
  if (matchStarts.length === 0) return null;

  const order = matchStarts
    .map((_, i) => i)
    .sort((a, b) => matchStarts[a]! - matchStarts[b]!);
  const starts: MatchSite[] = order.map((i) => ({
    lineIndex: source.slice(0, matchStarts[i]).split("\n").length - 1,
    symbol: matchSymbols[i],
  }));

  const chunks: Chunk[] = [];

  if (starts[0]!.lineIndex > 0) {
    const preambleText = lines.slice(0, starts[0]!.lineIndex).join("\n").trim();
    if (preambleText) {
      chunks.push({
        text: preambleText,
        startLine: 1,
        endLine: starts[0]!.lineIndex,
        symbol: undefined,
        chunkType: "block",
      });
    }
  }

  for (let i = 0; i < starts.length; i++) {
    const { lineIndex, symbol } = starts[i]!;
    const endLineIndex =
      i + 1 < starts.length ? starts[i + 1]!.lineIndex : lines.length;
    const text = lines.slice(lineIndex, endLineIndex).join("\n").trim();
    if (text) {
      chunks.push({
        text,
        startLine: lineIndex + 1,
        endLine: endLineIndex,

        symbol,
        chunkType: detectChunkType(lines[lineIndex]!),
      });
    }
  }

  return chunks;
}

/**
 * Chunks `content` at the regex-derived top-level declaration
 * boundaries for `extension` (if any). Returns `null` -- never throws
 * -- whenever `extension` has no table entry or zero matches are found,
 * signalling the caller (`indexing.ts`) to fall back to `chunkText`.
 */

export function chunkWithRegexPatterns(
  content: string,
  extension: string,
): Chunk[] | null {
  let patterns = REGEX_TABLE[extension];
  if (!patterns) return null;
  patterns = Array.isArray(patterns) ? patterns : [patterns];

  // TypeScript's own fallback tier additionally retries with _TS_ARROW
  // when _TS_TOP finds nothing (chunker.py's ".ts"/".tsx" case) -- JS/JSX
  // doesn't get that retry in the original (its case block only ever
  // calls _chunk_by_pattern(lines, _TS_TOP) once), so this module
  // deliberately folds the arrow pattern into JS_TOP's own pattern list
  // instead of a conditional retry, which is behaviorally equivalent
  // (merged-and-sorted matches either way) but simpler to express here.
  if (extension === ".js" || extension === ".jsx") {
    patterns = [JS_TOP, JS_ARROW];
  }

  const lines = content.split("\n");
  return chunkByPattern(lines, patterns);
}

// capture-group shape: exactly one group, the bare declared name). ──────────

const KT_TOP =
  /^(?:(?:public|private|protected|internal|abstract|open|data|sealed|inline|suspend|override|companion)\s+)*(?:class|object|interface|fun|typealias)\s+(\w+)/gm;

// Shared by both TypeScript's own regex-fallback tier (not wired up yet,
// see indexing.ts's simplified dispatch) and JavaScript/JSX, which has no
// tree-sitter tier at all in this plugin and so always lands here.
const JS_TOP =
  /^(?:export\s+)?(?:default\s+)?(?:async\s+)?(?:abstract\s+)?(?:class|function|const|interface|type|enum)\s+(\w+)/gm;
const JS_ARROW = /^(?:export\s+)?const\s+(\w+)\s*[:=].*(?:=>|\bfunction\b)/gm;

const PY_TOP = /^(?:async\s+)?(?:class|def)\s+(\w+)/gm;

const SWIFT_TOP =
  /^(?:(?:public|private|internal|fileprivate|open|final|override|static|@objc|@objcMembers|@main)\s+)*(?:class|struct|enum|protocol|func|extension|typealias|actor)\s+(\w+)/gm;

// Receiver clause (if any) is consumed non-capturing so the single group
// always lands on the actual function/type name.
const GO_TOP = /^(?:func\s+(?:\([^)]*\)\s*)?|type\s+)(\w+)/gm;

const RUST_TOP =
  /^(?:pub(?:\([^)]*\))?\s+)?(?:async\s+)?(?:unsafe\s+)?(?:fn|struct|enum|trait|impl)\s+(?:<[^>]*>\s*)?(\w+)/gm;

const RUBY_TOP = /^(?:class|module|def)\s+(\w+(?:::\w+)*)/gm;

const PHP_TOP =
  /^(?:abstract\s+|final\s+)*(?:class|interface|trait|function)\s+&?(\w+)/gm;

const C_AGGREGATE =
  /^(?:typedef[ \t]+)?(?:struct|class|enum(?:[ \t]+class)?|union)\s+(\w+)/gm;

const C_CONTROL_KEYWORDS =
  "if|for|while|switch|catch|else|return|do|sizeof|defined";
const C_FUNCTION = new RegExp(
  `^(?:static[ \\t]+|inline[ \\t]+|extern[ \\t]+|virtual[ \\t]+|constexpr[ \\t]+|explicit[ \\t]+)*` +
    `[\\w:<>,*&\\t ]+?\\b(?!(?:${C_CONTROL_KEYWORDS})\\b)(\\w+)[ \\t]*` +
    `\\([^;{)]*\\)[ \\t]*(?:const[ \\t]*)?\\{`,
  "gm",
);

/** Extension -> one regex, or a list of regexes merged + sorted by position (C/C++'s two shapes). */
const REGEX_TABLE: Record<string, RegExp | RegExp[]> = {
  ".kt": KT_TOP,
  ".kts": KT_TOP,
  ".js": JS_TOP,
  ".jsx": JS_TOP,
  ".py": PY_TOP,
  ".swift": SWIFT_TOP,
  ".go": GO_TOP,
  ".rs": RUST_TOP,
  ".rb": RUBY_TOP,
  ".php": PHP_TOP,
  ".c": [C_AGGREGATE, C_FUNCTION],
  ".cc": [C_AGGREGATE, C_FUNCTION],
  ".cpp": [C_AGGREGATE, C_FUNCTION],
  ".cxx": [C_AGGREGATE, C_FUNCTION],
  ".h": [C_AGGREGATE, C_FUNCTION],
  ".hpp": [C_AGGREGATE, C_FUNCTION],
};

/**
 * Classifies a top-level declaration line into a `chunkType` --
 * language-agnostic (shared structural keywords across every language
 * this module covers), TS port of `_detect_chunk_type`.
 */

function detectChunkType(line: string): string {
  const stripped = line.replace(/^\s+/, "");

  if (NG_DECORATOR_RE.test(stripped)) return "component";

  if (/\b(?:function|fun|def|func|fn)\b\s/.test(stripped)) return "function";

  if (/^(?:export\s+)?const\s+\w+\s*[:=].*(?:=>|\bfunction\b)/.test(stripped))
    return "function";

  if (
    /\b(?:class|interface|struct|enum|record|protocol|actor|typealias|object|extension|namespace|delegate|trait|impl|module|union)\b|@interface\b/.test(
      stripped,
    )
  ) {
    return "class";
  }

  const controlRe = new RegExp(`^(?:${C_CONTROL_KEYWORDS})\\b`);
  if (/\)\s*(?:const\s*)?\{\s*$/.test(stripped) && !controlRe.test(stripped)) {
    return "function";
  }

  return "block";
}

export async function walkRepoFiles(
  worktree: string,
  options: { exclude?: string[] } = {},
): Promise<string[]> {
  const results: string[] = [];
  const shouldIndexFile = createFileFilter(worktree, options);
  const excluded = createExcludeMatcher(options.exclude);

  async function walk(dirAbsolute: string, dirRelative: string): Promise<void> {
    const entries = await fs.readdir(dirAbsolute, { withFileTypes: true });
    for (const entry of entries) {
      const relative = dirRelative
        ? `${dirRelative}/${entry.name}`
        : entry.name;
      if (entry.isDirectory()) {
        if (SKIP_DIR_NAMES.has(entry.name)) continue;
        if (dirRelative === "" && entry.name === ".opencode") continue; // this plugin's own metadata dir
        if (excluded.isIgnored(`${relative}/`)) continue; // user-excluded directory: never descend
        await walk(path.join(dirAbsolute, entry.name), relative);
      } else if (entry.isFile()) {
        if (shouldIndexFile(relative)) results.push(relative);
      }
    }
  }

  await walk(worktree, "");
  return results;
}

export function mayChangeFiles(tool: string): boolean {
  return FILE_CHANGING_TOOLS.has(tool) || /^idea_(apply_patch|create_new_file|rename_refactoring|reformat_file|execute_terminal_command)$/.test(tool);
}

export interface RescanStats {
  runs: number;
  lastRunAt: string | null;
  lastTrigger: string | null;
  lastFilesOnDisk: number | null;
}

export interface RescanTriggerOptions {
  debounceMs?: number;
  /** Does one rescan; resolves with the number of files found on disk. */
  run: () => Promise<number | undefined>;
  onError?: (error: unknown) => void;
}

export interface RescanTrigger {
  /** Request a rescan after `debounceMs` of quiet; bursts coalesce into one run. */
  notify(trigger: string): void;
  /** Run now (waits for a running rescan, then runs once more if more was requested). */
  runNow(trigger: string): Promise<void>;
  stats(): RescanStats;
}

export function createRescanTrigger(options: RescanTriggerOptions): RescanTrigger {
  const debounceMs = options.debounceMs ?? 3000;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let running: Promise<void> | undefined;
  let again: string | undefined;
  const state: RescanStats = { runs: 0, lastRunAt: null, lastTrigger: null, lastFilesOnDisk: null };

  async function execute(trigger: string): Promise<void> {
    if (running) {
      again = trigger; // a running scan may have missed the change: run once more afterwards
      return running;
    }
    running = (async () => {
      let next: string | undefined = trigger;
      while (next !== undefined) {
        const current: string = next;
        again = undefined;
        try {
          const files = await options.run();
          state.runs++;
          state.lastRunAt = new Date().toISOString();
          state.lastTrigger = current;
          if (typeof files === "number") state.lastFilesOnDisk = files;
        } catch (error) {
          options.onError?.(error);
        }
        next = again;
      }
    })().finally(() => {
      running = undefined;
    });
    return running;
  }

  return {
    notify(trigger) {
      if (timer !== undefined) clearTimeout(timer);
      timer = setTimeout(() => {
        timer = undefined;
        void execute(trigger);
      }, debounceMs);
      timer.unref?.();
    },
    async runNow(trigger) {
      if (timer !== undefined) {
        clearTimeout(timer);
        timer = undefined;
      }

      await execute(trigger);
    },
    stats: () => ({ ...state }),
  };
}

import nodeFs from "node:fs";
import path from "node:path";
import type { IndexProgressSnapshot } from "./index-progress.js";

/**
 * Mirrors the progress tracker into `.opencode/ai-context/index-status.json`
 * so a user can follow indexing with e.g. `watch -n1 cat <file>`, no matter
 * which frontend (opencode TUI, JetBrains AI Assistant via ACP, ...) hosts
 * the plugin. The file lives in the worktree, so file-filter.ts must keep
 * excluding `.opencode/ai-context/` -- otherwise every write would come
 * back as a `file.watcher.updated` event and be indexed.
 */

export const STATUS_FILE_VERSION = 1;
const DEFAULT_THROTTLE_MS = 2000;

export function resolveStatusFilePath(worktree: string): string {
  return path.join(worktree, ".opencode", "ai-context", "index-status.json");
}

export interface StatusFileFs {
  mkdirSync(dir: string, options: { recursive: true }): unknown;
  writeFileSync(file: string, data: string): unknown;
  renameSync(from: string, to: string): unknown;
}

export interface StatusFileWriterOptions {
  filePath: string;
  fs?: StatusFileFs;
  now?: () => number;
  throttleMs?: number;
  /** Called when the status file cannot be written. */
  onError?: (error: unknown) => void;
}

export interface StatusFileWriter {
  write(snapshot: IndexProgressSnapshot): void;
}

const iso = (ms: number | null) =>
  ms === null ? null : new Date(ms).toISOString();

function serialize(s: IndexProgressSnapshot): string {
  return JSON.stringify(
    {
      version: STATUS_FILE_VERSION,
      ...s,
      startedAt: iso(s.startedAt),
      updatedAt: iso(s.updatedAt),
      finishedAt: iso(s.finishedAt),
      failures: s.failures.map((f) => ({
        ...f,
        lastFailedAt: iso(f.lastFailedAt),
      })),
    },
    null,
    2,
  );
}

export function createStatusFileWriter(
  options: StatusFileWriterOptions,
): StatusFileWriter {
  const fs = options.fs ?? nodeFs;
  const now = options.now ?? Date.now;
  const throttleMs = options.throttleMs ?? DEFAULT_THROTTLE_MS;
  let lastWriteAt: number | null = null;
  let lastPhase: string | null = null;
  let lastFailed = 0;
  let counter = 0;

  return {
    write(snapshot) {
      const significant =
        snapshot.phase !== lastPhase || snapshot.failed !== lastFailed;
      const t = now();
      if (!significant && lastWriteAt !== null && t - lastWriteAt < throttleMs)
        return;
      lastWriteAt = t;
      lastPhase = snapshot.phase;
      lastFailed = snapshot.failed;
      try {
        fs.mkdirSync(path.dirname(options.filePath), { recursive: true });
        const tmp = `${options.filePath}.${process.pid}.${counter++}.tmp`;
        fs.writeFileSync(tmp, serialize(snapshot));
        fs.renameSync(tmp, options.filePath);
      } catch (error) {
        // progress reporting is best-effort and must never interrupt indexing
        options.onError?.(error);
      }
    },
  };
}

function findDecoratorStart(declarationStartLine: number, lines: string[]): number | undefined {
  let idx = declarationStartLine - 2; // 0-based index of the line just above
  if (idx >= 0 && !lines[idx]!.trim()) {
    idx -= 1; // allow exactly one blank line between decorator and declaration
  }
  if (idx < 0) return undefined;

  const candidate = lines[idx]!.trim();
  if (NG_DECORATOR_RE.test(candidate)) {
    return idx + 1; // single-line decorator, e.g. "@Injectable()"
  }

  if (!/[)}\]]$/.test(candidate)) {
    return undefined; // not the tail of a bracketed decorator call
  }

  // Walk backward, depth-counting brackets, to find the decorator
  // call's own opening line.
  let depth = 0;
  for (let j = idx; j >= 0; j--) {
    const line = lines[j]!;
    for (let k = line.length - 1; k >= 0; k--) {
      const ch = line[k];
      if (ch === ")" || ch === "}" || ch === "]") {
        depth += 1;
      } else if (ch === "(" || ch === "{" || ch === "[") {
        depth -= 1;
        if (depth === 0) {
          return NG_DECORATOR_RE.test(line.trim()) ? j + 1 : undefined;
        }
      }
    }
  }
  return undefined; // unbalanced brackets -- bail out rather than overshoot
}

/**
 * Extends class/function chunks backward across a preceding Angular
 * decorator, shrinking the previous chunk's end line to match so the
 * two chunks stay non-overlapping (dropping the previous chunk
 * entirely if it becomes empty -- e.g. it was only the decorator,

export function applyDecoratorFix(chunks: TreeSitterChunk[], content: string, extension: string): TreeSitterChunk[] {
  if (extension !== ".ts" && extension !== ".tsx") return chunks;

  const lines = content.split("\n");
  const result = chunks.map((c) => ({ ...c }));

  for (let i = 0; i < result.length; i++) {
    const chunk = result[i]!;
    if (chunk.chunkType !== "class" && chunk.chunkType !== "function") continue;

    const decoratorStart = findDecoratorStart(chunk.startLine, lines);
    if (decoratorStart === undefined || decoratorStart >= chunk.startLine) continue;

    if (i > 0) {
      const prev = result[i - 1]!;
      if (prev.endLine >= decoratorStart) {
        prev.endLine = decoratorStart - 1;
        prev.text = lines
          .slice(prev.startLine - 1, prev.endLine)
          .join("\n")
          .trim();
      }
    }

    chunk.startLine = decoratorStart;
    chunk.text = lines
      .slice(decoratorStart - 1, chunk.endLine)
      .join("\n")
      .trim();
  }

  return result.filter((c) => c.text);
}

    const armText = lines.slice(armLine, armEndLine).join("\n").trim();
    if (armText) {
      result.push({
        text: armText,
        startLine: chunk.startLine + armLine,
        endLine: chunk.startLine + armEndLine - 1,
        symbol: label,
        chunkType: "case",
      });
    }
  }

  return result.length > 0 ? result : [chunk];
}

/**
 * Runs `chunkDispatchArms` over every chunk, for the extensions listed
 * in `DISPATCH_EXTENSIONS` -- a no-op (returns `chunks` unchanged) for
 * every other extension.
 */
/**
 * Runs `chunkDispatchArms` over every chunk, for extensions with a
 * `DISPATCH_TABLE` entry -- a no-op (returns `chunks` unchanged) for
 * every other extension.
 */

export function applyDispatchSubchunking(chunks: TreeSitterChunk[], extension: string): TreeSitterChunk[] {
  const pair = DISPATCH_TABLE[extension];
  if (!pair) return chunks;
  const [dispatchStartRe, armStartRe] = pair;
  return chunks.flatMap((c) => chunkDispatchArms(c, dispatchStartRe, armStartRe));
}

 * header line itself (e.g. `switch (x) {`) -- the arm-start regex's
 * leading `\s*` eats the newline right after the block's opening `{`,
 * shifting the computed line offset for that one arm back by one line,
 * so the header ends up merged into the first "case" chunk instead of
 * the head chunk. Subsequent arms are unaffected. See
 * dispatch-subchunking.test.ts's first test for the exact repro.
 */

const SWITCH_START = /\bswitch\s*\(/;
const SWITCH_ARM = /^\s*case\s+(.+?):/gm;
const WHEN_START = /\bwhen\s*[({]/;
const WHEN_ARM = /^\s*(.+?)\s*->/gm;
const MATCH_START = /\bmatch\s+.+:/;
const MATCH_ARM = /^\s*case\s+(.+?):/gm;

const MIN_ARMS_FOR_SUBCHUNK = 3; // heuristic gate, matches chunker.py

// Extension -> (dispatch-start-re, arm-start-re) -- mirrors chunker.py's
// own `_DISPATCH_TABLE` exactly. Extensions not listed here get no
// dispatch sub-chunking (e.g. Go/Rust/Ruby/PHP/C -- out of scope for
// this pass; their own top-level chunking is unaffected).
const DISPATCH_TABLE: Record<string, [RegExp, RegExp]> = {
  ".ts": [SWITCH_START, SWITCH_ARM],
  ".tsx": [SWITCH_START, SWITCH_ARM],
  ".js": [SWITCH_START, SWITCH_ARM],
  ".jsx": [SWITCH_START, SWITCH_ARM],
  ".java": [SWITCH_START, SWITCH_ARM],
  ".cs": [SWITCH_START, SWITCH_ARM],
  ".swift": [SWITCH_START, SWITCH_ARM],
  ".kt": [WHEN_START, WHEN_ARM],
  ".kts": [WHEN_START, WHEN_ARM],
  ".py": [MATCH_START, MATCH_ARM],
};

/**
 * Finds the `{...}` extent of a brace-delimited dispatch block,

function dispatchBlockSpan(bodyText: string, dispatchMatchEnd: number): [number, number] | undefined {
  const openPos = bodyText.indexOf("{", dispatchMatchEnd);
  if (openPos === -1) return undefined;
  let depth = 0;
  for (let i = openPos; i < bodyText.length; i++) {
    const ch = bodyText[i];
    if (ch === "{") depth += 1;
    else if (ch === "}") {
      depth -= 1;
      if (depth === 0) return [openPos + 1, i];
    }
  }
  return [openPos + 1, bodyText.length]; // unbalanced braces -- scope to end
}

/**
 * Given one already-produced chunk, checks whether its body contains a
