case ".cs":
      return TREE_SITTER_LANGUAGES.csharp;
    default:
      return undefined;
  }
}

export interface TreeSitterLanguageConfig {
  /** `tree-sitter-wasms`' own grammar filename stem (e.g. "c_sharp", not "csharp"). */
  grammarName: string;
  /** Top-level declaration node types this language's chunk boundaries are drawn at. */
  nodeTypes: ReadonlySet<string>;
  /**
   * Node types that are pure organizational containers (recursed
   * through, never themselves emitted as a chunk boundary) -- e.g. a
   * C# `namespace_declaration` wrapping many classes/interfaces should
   * not collapse all of them into one giant chunk.
   */
  containerOnlyNodeTypes: ReadonlySet<string>;
}

/** Node type -> human-readable chunk_type, shared across all Tier-1 languages (symbol_extractor.py's `_KIND_MAP`). */
export const KIND_MAP: Readonly<Record<string, string>> = {
  class_declaration: "class",
  class_definition: "class",
  function_declaration: "function",
  function_definition: "function",
  method_declaration: "method",
  method_definition: "method",
  constructor_declaration: "constructor",
  secondary_constructor: "constructor",
  initializer_declaration: "initializer",
  interface_declaration: "interface",
  enum_declaration: "enum",
  struct_declaration: "struct",
  record_declaration: "record",
  namespace_declaration: "namespace",
  object_declaration: "object",
  protocol_declaration: "protocol",
  extension_declaration: "extension",
  type_alias_declaration: "typealias",
};

/** This plugin's own language ids (indexing.ts's `guessLanguage`) -> tree-sitter chunk-boundary config. */

export type TreeSitterGrammarName = keyof typeof GRAMMAR_WASM;

// Resolved via Node module resolution from this file's location, so it
// works from src/ (tests) and from the bundled dist/ file alike, as long
// as the grammar packages are installed next to it.
const requireFromHere = createRequire(import.meta.url);

let parserInitialized: Promise<void> | undefined;

function ensureParserInitialized(): Promise<void> {
  parserInitialized ??= Parser.init();
  return parserInitialized;
}

const languageCache = new Map<string, Promise<Language>>();

/**
 * Loads (and caches, per grammar name) a `Language` from its
 * `.wasm` file. Rejects if `grammarName` isn't one of `GRAMMAR_WASM`
 * or its `.wasm` file can't be loaded -- callers (language-grammars.ts's
 * dispatch) are expected to catch and fall back to
 * `chunkText`'s paragraph-based chunker, matching chunker.py's own
 * `_chunk_by_treesitter` returning `None` on any failure.
 */

export async function loadTreeSitterLanguage(grammarName: string): Promise<Language> {
  const wasmSpecifier = GRAMMAR_WASM[grammarName];
  if (!wasmSpecifier) {
    throw new Error(`no tree-sitter grammar for "${grammarName}"`);
  }

  let cached = languageCache.get(grammarName);
  if (!cached) {
    cached = (async () => {
      await ensureParserInitialized();
      return Language.load(requireFromHere.resolve(wasmSpecifier));
    })();
    languageCache.set(grammarName, cached);
  }
  return cached;
}

/** Convenience: a ready-to-use `Parser` with `grammarName`'s language already set. */

export async function createTreeSitterParser(grammarName: string): Promise<Parser> {
  const language = await loadTreeSitterLanguage(grammarName);
  const parser = new Parser();
  parser.setLanguage(language);
  return parser;
}

export interface TreeSitterChunk {
  text: string;
  startLine: number;
  endLine: number;
  symbol: string | undefined;
  chunkType: string;
}

interface DeclarationSite {
  /** 1-based line number. */
  startLine: number;
  name: string | undefined;
  nodeType: string;
}

/**
 * Collects (startLine, name, nodeType) for every top-level declaration
 * node, using the parse tree instead of indentation/regexes.
 * Deliberately does NOT descend into a matched node's own children -- a
 * class's methods stay inside its single chunk, exactly like the
 * original regex chunker's `^`-anchored patterns never matching
 * indented methods either (see chunker.py's `_collect_top_level`
 * docstring: "this is a chunk-*boundary* swap-in, not a request to
 * chunk at every nested node"). `containerOnlyNodeTypes` (e.g. a C#
 * `namespace_declaration`) are the one exception: always recursed
 * through, never emitted as a boundary themselves.
 */

function collectTopLevel(node: Node, config: TreeSitterLanguageConfig): DeclarationSite[] {
  const results: DeclarationSite[] = [];

  function visit(n: Node): void {
    if (config.nodeTypes.has(n.type) && !config.containerOnlyNodeTypes.has(n.type)) {
      const nameNode = n.childForFieldName("name");
      results.push({
        startLine: n.startPosition.row + 1,
        name: nameNode?.text,
        nodeType: n.type,
      });
      return; // do not descend further -- see docstring above
    }
    for (const child of n.children) {
      visit(child);
    }
  }

  visit(node);
  results.sort((a, b) => a.startLine - b.startLine);
  return results;
}

/**
 * Parses `content` with the Tier-1 tree-sitter grammar for `extension`
 * (if any) and slices it into chunks at each top-level declaration's
 * boundary, with a leading "preamble" chunk (imports/package
 * declarations/annotations before the first declaration) matching
 * `_chunk_by_treesitter`'s own preamble convention. Returns `null` --
 * never throws -- for any condition that should fall back to
 * `chunkText` instead (see this module's own doc comment).
 */

export async function chunkWithTreeSitter(content: string, extension: string): Promise<TreeSitterChunk[] | null> {
  const config = treeSitterConfigForExtension(extension);
  if (!config) return null;

  let parser: Parser;
  try {
    parser = await createTreeSitterParser(config.grammarName);
  } catch {
    return null;
  }

  let tree: Tree | null;
  try {
    tree = parser.parse(content);
  } catch {
    return null;
  }
  if (!tree) return null;

  const lines = content.split("\n");
  const declarations = collectTopLevel(tree.rootNode, config);
  if (declarations.length === 0) return null;

  const chunks: TreeSitterChunk[] = [];

  const firstStart = declarations[0]!.startLine;
  if (firstStart > 1) {
    const preambleText = lines
      .slice(0, firstStart - 1)
      .join("\n")
      .trim();
    if (preambleText) {
      chunks.push({
        text: preambleText,
        startLine: 1,
        endLine: firstStart - 1,
        symbol: undefined,
        chunkType: "block",
      });
    }
  }

  for (let i = 0; i < declarations.length; i++) {
    const { startLine, name, nodeType } = declarations[i]!;
    const endLine = i + 1 < declarations.length ? declarations[i + 1]!.startLine - 1 : lines.length;
    const text = lines
      .slice(startLine - 1, endLine)
      .join("\n")
      .trim();
    if (text) {
      chunks.push({
        text,
        startLine,
        endLine,
        symbol: name,
        chunkType: KIND_MAP[nodeType] ?? "block",
      });
    }
  }

  return chunks;
}

import { appendFileSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";

/**
 * Persistent, human-readable record of everything that went wrong
 * (`.opencode/ai-context/error.log.md`). Entries are buffered until
 * `activate()` so a disabled plugin writes nothing; the file is capped by
 * dropping the oldest entries. Never throws.
 */

export interface ErrorLog {
  record(context: string, error?: unknown): void;
  /** Start writing; flushes entries recorded before. */
  activate(): void;
}

export interface ErrorLogOptions {
  filePath: string;
  now?: () => Date;
  maxBytes?: number;
}

const HEADER =
  "# Error log\n\n<!-- generated by opencode-ai-context-plugin; newest entries last, oldest are dropped -->\n";
const DEFAULT_MAX_BYTES = 256 * 1024;
const MAX_BUFFERED = 100;

export function createErrorLog(options: ErrorLogOptions): ErrorLog {
  const now = options.now ?? (() => new Date());
  const maxBytes = options.maxBytes ?? DEFAULT_MAX_BYTES;
  let active = false;
  let buffer: string[] = [];

  const write = (entry: string) => {
    try {
      mkdirSync(dirname(options.filePath), { recursive: true });
      let current = "";
      try {
        current = readFileSync(options.filePath, "utf8");
      } catch {
        // first write
      }
      if (!current.startsWith("# Error log")) current = HEADER;
      let next = current + entry;
      if (Buffer.byteLength(next) > maxBytes) {
        const entries = next.slice(HEADER.length).split(/(?=\n## )/);
        while (entries.length > 1 && Buffer.byteLength(HEADER + entries.join("")) > maxBytes) entries.shift();
        next = HEADER + entries.join("");
        writeFileSync(options.filePath, next);
      } else if (current === HEADER) {
        writeFileSync(options.filePath, next);
      } else {
        appendFileSync(options.filePath, entry);
      }
    } catch {
      // logging must never break the plugin
    }
  };

  const format = (context: string, error?: unknown) => {
    const detail =
      error === undefined ? "" : error instanceof Error ? (error.stack ?? error.message) : String(error);
    return `\n## ${now().toISOString()} — ${context}\n${detail ? `\n\`\`\`\n${detail}\n\`\`\`\n` : ""}`;
  };

  return {
    record(context, error) {
      const entry = format(context, error);
      if (active) write(entry);

      else if (buffer.length < MAX_BUFFERED) buffer.push(entry);
    },
    activate() {
      if (active) return;
      active = true;
      for (const entry of buffer) write(entry);
      buffer = [];
    },
  };
}

import { execFile } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/**
 * Native OS notifications: the only status channel that reaches the user
 * under every frontend, including JetBrains AI Assistant via ACP
 * (docs/opencode-plugin-workarounds.md §1e). Best-effort by design.
 */

export interface OsNotifyRunner {
  run(command: string, args: string[]): void;
}

const defaultRunner: OsNotifyRunner = {

run(command, args) {
    execFile(command, args, () => {
      // notifications must never crash the plugin
    });
  },
};

export function appleScriptString(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

export function notifyOs(
  message: string,
  options: {
    title?: string;
    platform?: NodeJS.Platform;
    runner?: OsNotifyRunner;
  } = {},
): void {
  const platform = options.platform ?? process.platform;
  const runner = options.runner ?? defaultRunner;
  const title = options.title ?? "AI Context";

  if (platform === "darwin") {
    runner.run("osascript", [
      "-e",
      `display notification "${appleScriptString(message)}" with title "${appleScriptString(title)}"`,
    ]);
  } else if (platform === "linux") {
    runner.run("notify-send", [title, message]);
  }
}

/** opencode bootstraps plugins twice per session; this suppresses the duplicate one-shot popup. */

export interface OsNotifyGate {
  shouldNotify(): boolean;
}

export function createOsNotifyGate(
  options: { windowMs?: number; now?: () => number } = {},
): OsNotifyGate {
  const windowMs = options.windowMs ?? 10_000;
  const now = options.now ?? Date.now;
  let lastFiredAt: number | undefined;
  return {
    shouldNotify() {
      const t = now();
      if (lastFiredAt !== undefined && t - lastFiredAt < windowMs) return false;
      lastFiredAt = t;
      return true;
    },
  };
}

export const defaultOsNotifyGate = createOsNotifyGate();

/**
 * Like {@link createOsNotifyGate} but shared across processes (several opencode/ACP
 * processes can start at once) via a marker file whose mtime is the last firing time.
 */

export function createFileOsNotifyGate(
  options: {
    key: string;
    dir?: string;
    windowMs?: number;
    now?: () => number;
  },
): OsNotifyGate {
  const windowMs = options.windowMs ?? 5 * 60_000;
  const now = options.now ?? Date.now;
  const file = path.join(
    options.dir ?? os.tmpdir(),
    `opencode-ai-context-${options.key}.notified`,
  );
  return {
    shouldNotify() {
      try {
        const t = now();
        try {
          const age = t - fs.statSync(file).mtimeMs;
          if (age >= 0 && age < windowMs) return false;
          fs.unlinkSync(file);
        } catch (error) {
          if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
        }
        fs.writeFileSync(file, "", { flag: "wx" });
        fs.utimesSync(file, t / 1000, t / 1000);
        return true;
      } catch {
        // lost the race to another process, or no writable tmp dir
        return false;
      }
    },
  };
}

export interface ProblemReporterOptions {
  notify: (message: string) => void;
  log?: (message: string) => void;
  now?: () => number;
  windowMs?: number;
  seen?: Map<string, number>;
  /** Called for every report, before deduplication (persistent error log). */
  record?: (context: string, error?: unknown) => void;
}

const MAX_MESSAGE_CHARS = 200;
const sharedSeen = new Map<string, number>();

export function createProblemReporter(
  options: ProblemReporterOptions,
): ProblemReporter {
  const log =
    options.log ??
    ((message: string) =>
      console.error(`[opencode-ai-context-plugin] ${message}`));
  const now = options.now ?? Date.now;
  const windowMs = options.windowMs ?? 60_000;
  const seen = options.seen ?? sharedSeen;

  return {
    report(context, error) {
      const reason =
        error === undefined
          ? ""
          : error instanceof Error
            ? error.message
            : String(error);
      try {
        options.record?.(context, error);
      } catch {
        // reporting must never throw
      }
      const full = reason ? `${context}: ${reason}` : context;
      try {
        log(full);
      } catch {
        // reporting must never throw
      }
      const t = now();
      const last = seen.get(full);
      if (last !== undefined && t - last < windowMs) return;
      seen.set(full, t);
      const message =
        full.length > MAX_MESSAGE_CHARS
          ? `${full.slice(0, MAX_MESSAGE_CHARS - 1)}…`
          : full;
      try {
        options.notify(message);
      } catch {
        // reporting must never throw
      }
    },
  };
}

export interface ProblemReporter {
  report(context: string, error?: unknown): void;
}

import {
  HEALING_REASONS,
  type IndexProgressSnapshot,
} from "../indexing/index-progress.js";

export const DEFAULT_MIN_FILES_FOR_NOTICE = 20;

function describeReasons(reasons: IndexProgressSnapshot["reasons"]): string {
  return Object.entries(reasons)
    .filter(([, count]) => (count ?? 0) > 0)
    .map(([reason, count]) => `${count} ${REASON_LABELS[reason] ?? reason}`)
    .join(", ");
}

/** Turns tracker snapshots into at most three popups per run: started, finished, failed. */

export function createProgressNotifier(
  options: ProgressNotifierOptions,
): (snapshot: IndexProgressSnapshot) => void {
  const min = options.minFilesForNotice ?? DEFAULT_MIN_FILES_FOR_NOTICE;
  let startAnnounced = false;
  let failureAnnounced = false;
  let healingRun = false;

  return (s) => {
    if (s.phase === "failed") {
      if (!failureAnnounced) {
        failureAnnounced = true;
        options.notify(`Indexing failed: ${s.lastError ?? "unknown error"}`);
      }
      startAnnounced = false;
      return;
    }
    failureAnnounced = false;

    const healing = HEALING_REASONS.some((r) => (s.reasons[r] ?? 0) > 0);
    if (s.running && s.total > 0 && (s.total >= min || healing) && !startAnnounced) {
      startAnnounced = true;
      healingRun = healing;
      const progressFile = "Progress: .opencode/ai-context/index-status.json";
      options.notify(
        healing
          ? `Updating index: ${s.total} files (${describeReasons(s.reasons)}). ${progressFile}`
          : `Indexing started: ${s.total} files. ${progressFile}`,
      );
    } else if (s.phase === "done" && startAnnounced) {
      startAnnounced = false;
      const skipped = s.failed > 0 ? `, ${s.failed} skipped` : "";
      options.notify(
        `${healingRun ? "Index update finished" : "Indexing finished"}: ${s.total} files${skipped}.`,
      );
    } else if (s.phase === "done" || s.phase === "idle") {
      startAnnounced = false;
    }
  };
}

export interface ProgressNotifierOptions {
  notify: (message: string) => void;
  /** Runs smaller than this (single watcher edits) stay silent; failures always notify. */
  minFilesForNotice?: number;
}

const REASON_LABELS: Record<string, string> = {
  upgrade: "new index format",
  repair: "repaired",
  summaries: "adding summaries",
  new: "new",
  changed: "changed",
  removed: "removed",
};

