  const trees = store
    .getAllTrees()
    .filter((t) => t.relativePath.startsWith(prefix));
  if (!trees.length) return [];

  const queryTerms = query
    .toLowerCase()
    .split(/\W+/)
    .filter((t) => t.length >= 3);

  const ranked = trees
    .map((record) => {
      const pathLower = record.relativePath.toLowerCase();
      const pathHits = queryTerms.filter((t) => pathLower.includes(t)).length;
      const scored = mode === "toc_only" ? [] : scoreNodes(record.nodes, queryTerms);
      const selectedIds = selectNodesByKeyword(scored, 5);
      const nodeScore = scored.reduce((best, n) => Math.max(best, n.score), 0);
      return { record, pathHits, selectedIds, score: pathHits * 2 + nodeScore };
    })
    .filter((r) => mode === "toc_only" || r.score > 0)
    .sort(
      (a, b) =>
        b.score - a.score || a.record.relativePath.localeCompare(b.record.relativePath),
    );

  const start = Math.max(0, options.offset ?? 0);
  const results: DocTreeSearchResult[] = [];
  for (const { record, selectedIds } of ranked.slice(start, start + limit)) {
    const toc = buildToc(record.relativePath, record);
    if (mode === "toc_only") {
      results.push({ relativePath: record.relativePath, toc, relevantNodes: [] });
      continue;

    }
    const relevantNodes: DocTreeSearchNode[] = [];
    for (const nodeId of selectedIds) {
      const node = findNodeById(record.nodes, nodeId);
      if (!node) continue;
      const entry: DocTreeSearchNode = {
        nodeId: node.nodeId,
        title: node.title,
        startLine: node.startLine,
        endLine: node.endLine,
        summary: node.summary,
      };
      if (mode === "node_text") entry.text = node.bodyText;
      relevantNodes.push(entry);
    }
    results.push({ relativePath: record.relativePath, toc, relevantNodes });
  }
  return results;
}

export interface DocTreeSearchNode {
  nodeId: string;
  title: string;
  startLine: number;
  endLine: number;
  summary: string | null;
  /** Only populated in "node_text" mode. */
  text?: string;
}

export interface DocTreeSearchResult {
  relativePath: string;
  toc: string;
  relevantNodes: DocTreeSearchNode[];
}

/** Port of doc_tree.ts's `buildToc`. */

export function buildToc(relativePath: string, tree: DocTree): string {
  function flatten(nodes: DocTreeNode[], indent = 0): string[] {
    const prefix = "  ".repeat(indent);
    const lines: string[] = [];
    for (const node of nodes) {
      const summary = node.summary ? `: "${node.summary}"` : "";
      lines.push(`${prefix}[${node.nodeId}] ${node.title} (lines ${node.startLine}–${node.endLine})${summary}`);
      lines.push(...flatten(node.children, indent + 1));
    }
    return lines;
  }

  const header = `# ${relativePath}` + (tree.description ? `\n_${tree.description}_` : "");
  return header + "\n" + flatten(tree.nodes).join("\n");
}

function findNodeById(nodes: DocTreeNode[], nodeId: string): DocTreeNode | null {
  for (const node of nodes) {
    if (node.nodeId === nodeId) return node;
    const found = findNodeById(node.children, nodeId);
    if (found) return found;
  }
  return null;
}

export interface DocTreeSearchOptions {
  /** Only docs below this repo-relative directory. */
  dirPath?: string;
  /** Skip this many ranked files (paging). */
  offset?: number;
}

interface ScoredNode {
  nodeId: string;
  score: number;
}

function scoreNodes(nodes: DocTreeNode[], queryTerms: string[]): ScoredNode[] {
  const flat: ScoredNode[] = [];
  function traverse(ns: DocTreeNode[]): void {
    for (const node of ns) {
      const text = `${node.title} ${node.summary ?? ""}`.toLowerCase();
      let hits = 0;
      for (const term of queryTerms) if (text.includes(term)) hits++;
      flat.push({ nodeId: node.nodeId, score: hits });
      traverse(node.children);
    }
  }
  traverse(nodes);
  return flat;
}

/** Port of doc_tree.ts's `selectNodesByKeyword`. */

function selectNodesByKeyword(scored: ScoredNode[], topN: number): string[] {
  return [...scored]
    .sort((a, b) => b.score - a.score)
    .slice(0, topN)
    .filter((x) => x.score > 0)
    .map((x) => x.nodeId);
}

function normalizeDir(dirPath: string | undefined): string {
  return (dirPath ?? "")
    .replace(/\\/g, "/")
    .replace(/^(\.\/)+/, "")
    .replace(/^\/+|\/+$/g, "")
    .replace(/^\.$/, "");
}

/**
 * Ranks ALL trees (not the first `limit` in storage order) and then pages.
 * `toc_only` lists every doc below `dirPath` (path matches of the query first,
 * then path order); the other modes keep only docs whose path or sections match.
 */

import type { VectorSearchResult, VectorStore } from "../storage/vector-store.js";

/** Standard reciprocal-rank-fusion constant (Cormack et al., 2009). */
export const RRF_K = 60;

/**
 * Reciprocal rank fusion: each list contributes 1/(k+rank) per item, so items
 * ranked well in several lists win without having to compare incompatible
 * scores (cosine similarity vs. BM25). Items are identified by `id`.
 */

export function fuseRankings<T extends VectorSearchResult>(
  lists: T[][],
  limit: number,
  k: number = RRF_K,
): T[] {
  const scores = new Map<string, { item: T; score: number }>();
  for (const list of lists) {
    list.forEach((item, index) => {
      const gain = 1 / (k + index + 1);
      const entry = scores.get(item.id);
      if (entry) entry.score += gain;
      else scores.set(item.id, { item, score: gain });
    });
  }
  return [...scores.values()]
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map(({ item, score }) => ({ ...item, score }));
}

export interface HybridSearchInput {
  query: string;
  vector: number[];
  limit: number;
  /** Candidates fetched per channel before fusion (default: 3x limit, at least 20). */
  candidates?: number;
}

/** Dense vector search and BM25 keyword search of one store, fused by RRF. */

export function hybridSearch(
  store: VectorStore,
  input: HybridSearchInput,
): VectorSearchResult[] {
  const candidates = input.candidates ?? Math.max(20, input.limit * 3);
  return fuseRankings(
    [
      store.search(input.vector, candidates),
      store.searchText(input.query, candidates),
    ],
    input.limit,
  );
}

export function extractTerms(query: string): string[] {
  const raw = query.split(/\W+/).filter(Boolean);
  const expanded: string[] = [];
  for (const token of raw) {
    expanded.push(token.toLowerCase());
    const parts = token.split(/(?<=[a-z])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])/);
    if (parts.length > 1) expanded.push(...parts.map((p) => p.toLowerCase()));
  }
  return [...new Set(expanded)].filter((t) => t.length >= MIN_TERM_LENGTH);
}

/** Counts (case-insensitive, overlap-free) term occurrences in `text`, scaled to [0, 1]. */

export function keywordScore(queryTerms: string[], text: string): number {
  if (queryTerms.length === 0) return 0;
  const lower = text.toLowerCase();
  let hits = 0;
  for (const term of queryTerms) {
    let pos = 0;
    while ((pos = lower.indexOf(term, pos)) !== -1) {
      hits++;
      pos += term.length;
    }
  }
  return Math.min(hits / 10, 1.0);
}

/**
 * Re-scores `hits` as `(1 - weight) * originalScore + weight * keywordScore`
 * and re-sorts descending. A stable sort keeps ties in their original
 * (dense-similarity-ranked) order rather than reshuffling them.
 */

export function keywordRerank<T extends VectorSearchResult>(query: string, hits: T[]): T[] {
  const terms = extractTerms(query);
  if (terms.length === 0) return [...hits];

  return hits
    .map((hit) => {
      const boost = KEYWORD_BOOST_WEIGHT * keywordScore(terms, hit.text);
      return { ...hit, score: (1 - KEYWORD_BOOST_WEIGHT) * hit.score + boost };
    })
    .sort((a, b) => b.score - a.score);
}

export interface RepoStructure {
  dirPath: string;
  found: boolean;
  entries: StructureEntry[];
  omitted: number;
}

export interface RepoStructureOptions {
  dirPath?: string;
  depth?: number;
  maxEntries?: number;
}

export const DEFAULT_DEPTH = 2;
export const DEFAULT_MAX_ENTRIES = 200;

export interface StructureEntry {
  path: string;
  type: "dir" | "file";
  /** Directories: number of indexed files below. */
  files?: number;
  /** Directories: languages found below, most frequent first. */
  languages?: string[];
  /** Files: language of the file. */
  language?: string;
}

function normalizeDir(dirPath: string | undefined): string {
  return (dirPath ?? "")
    .replace(/\\/g, "/")
    .replace(/^(\.\/)+/, "")
    .replace(/^\/+|\/+$/g, "")
    .replace(/^\.$/, "");
}

function topLanguages(counts: Map<string, number>): string[] {
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([l]) => l);
}

/**
 * Pure directory-tree view over the indexed files: directories first (with
 * file count and languages), then files, `depth` levels below `dirPath`.
 */

export function buildRepoStructure(
  files: IndexedFile[],
  options: RepoStructureOptions = {},
): RepoStructure {
  const dirPath = normalizeDir(options.dirPath);
  const depth = Math.max(1, options.depth ?? DEFAULT_DEPTH);
  const maxEntries = Math.max(1, options.maxEntries ?? DEFAULT_MAX_ENTRIES);
  const prefix = dirPath === "" ? "" : `${dirPath}/`;

  const dirs = new Map<string, { files: number; langs: Map<string, number> }>();
  const fileEntries: StructureEntry[] = [];
  let found = dirPath === "";

  for (const file of files) {
    if (!file.relativePath.startsWith(prefix)) continue;
    found = true;
    const segments = file.relativePath.slice(prefix.length).split("/");
    for (let level = 1; level < segments.length && level <= depth; level++) {
      const dir = prefix + segments.slice(0, level).join("/");
      const info = dirs.get(dir) ?? { files: 0, langs: new Map() };
      info.files += 1;
      info.langs.set(file.language, (info.langs.get(file.language) ?? 0) + 1);
      dirs.set(dir, info);
    }
    if (segments.length <= depth) {
      fileEntries.push({
        path: file.relativePath,
        type: "file",
        language: file.language,
      });
    }
  }

  const dirEntries: StructureEntry[] = [...dirs.entries()]
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([path, info]) => ({
      path,
      type: "dir",
      files: info.files,
      languages: topLanguages(info.langs),
    }));

  const all = [
    ...dirEntries,

    ...fileEntries.sort((a, b) => a.path.localeCompare(b.path)),
  ];
  return {
    dirPath,
    found,
    entries: all.slice(0, maxEntries),
    omitted: Math.max(0, all.length - maxEntries),
  };
}

