  options: ProjectKeyOptions = {},
): ProjectKeyResult {
  const dataDir = resolveDataDir(options);

  const normalized = path.resolve(worktree);
  const hash = createHash("sha256").update(normalized).digest("hex").slice(0, 8);
  const slug = slugify(path.basename(normalized));
  const key = `${slug}-${hash}`;

  return {
    key,
    // Deliberately OUTSIDE the worktree: if the db file lived inside the
    // watched project tree, the plugin's own writes to it would trigger
    // file.watcher.updated and re-index its own database file.
    dbPath: path.join(dataDir, "projects", key, "index.sqlite"),
  };
}

import fs from "node:fs";
import path from "node:path";
import { projectName, resolveDataDir, type ProjectKeyOptions } from "./project-key.js";

/**
 * Companion to `project-key.ts`'s per-project physical isolation
 * (plan.md, "multi-repo-isolation"): now that every project gets its own
 * directory (`<dataDir>/projects/<key>/`), this module gives the user a
 * way to see what's on disk and remove a project's data once its repo is
 * no longer in use -- otherwise the data dir only ever grows, since
 * nothing else in this plugin ever deletes a project directory.
 */

export interface ProjectInfo {
  /** The project's derived key (see project-key.ts:deriveProjectKey). */
  key: string;
  /** Stable name (key without the per-machine hash); what the agent and the allow-list use. */
  name: string;
  /** Absolute path to the project's vector-store file. */
  dbPath: string;
  /** Total size, in bytes, of everything under the project's directory. */
  sizeBytes: number;
  /** Last-modified time of the project's directory contents. */
  mtimeMs: number;
}

function projectsRoot(options: ProjectKeyOptions): string {
  return path.join(resolveDataDir(options), "projects");
}

function isValidKey(key: string): boolean {
  // Keys only ever come from deriveProjectKey's slug+hash format in
  // practice, but this is also reachable from a native tool with a
  // freeform argument -- reject anything that isn't a single path
  // segment before it's ever joined into a filesystem path.
  return key.length > 0 && !key.includes("/") && !key.includes("\\") && key !== "." && key !== "..";
}

function dirSizeBytes(dir: string): number {
  let total = 0;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const entryPath = path.join(dir, entry.name);
    try {
      total += entry.isDirectory() ? dirSizeBytes(entryPath) : fs.statSync(entryPath).size;
    } catch {
      // vanished meanwhile (index.lock, WAL files): not part of the size
    }
  }
  return total;
}

/** Lists every project currently stored under the data dir. */

export function listProjects(options: ProjectKeyOptions = {}): ProjectInfo[] {
  const root = projectsRoot(options);
  if (!fs.existsSync(root)) return [];

  return fs
    .readdirSync(root, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => {
      const dir = path.join(root, entry.name);
      return {
        key: entry.name,
        name: projectName(entry.name),
        dbPath: path.join(dir, "index.sqlite"),
        sizeBytes: dirSizeBytes(dir),
        mtimeMs: fs.statSync(dir).mtimeMs,
      };
    });
}

/**
 * Deletes a project's entire directory (its vector store and any other
 * per-project data). Returns `true` if a project with that key existed
 * and was removed, `false` if there was nothing to delete -- deliberately
 * not an error, so "delete a project that's already gone" is a no-op.
 */

export function deleteProject(key: string, options: ProjectKeyOptions = {}): boolean {
  if (!isValidKey(key)) {
    throw new Error(`Invalid project key: ${JSON.stringify(key)}`);
  }
  const dir = path.join(projectsRoot(options), key);
  if (!fs.existsSync(dir)) return false;
  fs.rmSync(dir, { recursive: true, force: true });
  return true;
}

export function addAllowedRepo(worktree: string, name: string): AddAllowedRepoResult {
  const existing = readAllowlist(worktree);
  if (existing.includes(name)) {
    return { added: false, keys: existing };
  }
  const keys = [...existing, name].sort();
  writeToYaml(worktree, keys);
  return { added: true, keys };
}

function legacyFilePath(worktree: string): string {
  return path.join(worktree, ".opencode", "ai-context", "config", "allowed-repos.json");
}

export interface AddAllowedRepoResult {
  added: boolean;
  keys: string[];
}

function normalize(entries: unknown): string[] {
  if (!Array.isArray(entries)) return [];
  return [
    ...new Set(
      entries.filter((e): e is string => typeof e === "string" && e.trim() !== "").map((e) => projectName(e.trim())),
    ),
  ].sort();
}

function readFromYaml(worktree: string): string[] {
  const filePath = resolveConfigFilePath(worktree);
  if (!fs.existsSync(filePath)) return [];
  try {
    const parsed = parseYaml(fs.readFileSync(filePath, "utf8")) as Record<string, unknown> | null;
    return normalize(parsed?.allowed_repos);
  } catch {
    return [];
  }
}

function writeToYaml(worktree: string, keys: string[]): void {
  const filePath = resolveConfigFilePath(worktree);
  const exists = fs.existsSync(filePath);
  const doc = parseDocument(exists ? fs.readFileSync(filePath, "utf8") : "");
  if (doc.errors.length > 0) {
    throw new Error(`cannot update allowed_repos: ${filePath} is not valid YAML (${doc.errors[0]!.message})`);
  }
  if (!doc.contents) doc.contents = doc.createNode({}) as unknown as typeof doc.contents;
  if (!doc.has("allowed_repos")) {
    const key = doc.createNode("allowed_repos");
    key.commentBefore = ALLOWED_REPOS_COMMENT;
    doc.set(key, keys);
  } else {
    doc.set("allowed_repos", keys);
  }
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, doc.toString());
}

const ALLOWED_REPOS_COMMENT =
  " Other indexed projects (names, no hash) that semantic_search and the project argument\n" +
  " may also look into. Written by the plugin (ai_context_allow_repo); manual edits are fine.";

/** Imports the legacy JSON allowlist into the YAML once and removes the old file. */

function migrateLegacy(worktree: string): void {
  const legacy = legacyFilePath(worktree);
  if (!fs.existsSync(legacy)) return;
  try {
    const old = normalize(JSON.parse(fs.readFileSync(legacy, "utf8")));
    const merged = normalize([...readFromYaml(worktree), ...old]);
    if (merged.length > 0) writeToYaml(worktree, merged);
    fs.rmSync(legacy);
    const dir = path.dirname(legacy);
    if (fs.readdirSync(dir).length === 0) fs.rmdirSync(dir);
  } catch {
    // keep the legacy file; retried on the next call
  }
}

export function readAllowlist(worktree: string): string[] {
  migrateLegacy(worktree);
  return readFromYaml(worktree);
}

/** Adds the project `name` to the allow-list, sorted and deduplicated. */

export interface SqliteStatement {
  run(...params: unknown[]): unknown;
  get(...params: unknown[]): unknown;
  all(...params: unknown[]): unknown[];
}

export interface SqliteDatabase {
  exec(sql: string): void;
  prepare(sql: string): SqliteStatement;
  /** `db.pragma("journal_mode = WAL")`; returns the resulting rows. */
  pragma(statement: string): unknown[];
  transaction<A extends unknown[]>(fn: (...args: A) => void): (...args: A) => void;
  close(): void;
}

const nodeRequire = createRequire(import.meta.url);

interface RawStatement {
  run(...p: unknown[]): unknown;
  get(...p: unknown[]): unknown;
  all(...p: unknown[]): unknown[];
}

interface RawDatabase {
  exec(sql: string): unknown;
  prepare(sql: string): RawStatement;
  transaction<A extends unknown[]>(fn: (...args: A) => void): (...args: A) => void;
  close(): void;
}

function openRaw(path: string): RawDatabase {
  if (process.versions.bun) {
    const { Database } = nodeRequire("bun:sqlite") as { Database: new (p: string, o: object) => RawDatabase };
    // strict: named parameters bind without their `@`/`$` prefix, like better-sqlite3.
    return new Database(path, { create: true, strict: true });
  }
  const BetterSqlite = nodeRequire("better-sqlite3") as new (p: string) => RawDatabase;
  return new BetterSqlite(path);
}

export function openDatabase(path: string): SqliteDatabase {
  const raw = openRaw(path);
  return {
    exec: (sql) => void raw.exec(sql),
    prepare: (sql) => {
      const stmt = raw.prepare(sql);
      return {
        run: (...p) => stmt.run(...p),
        get: (...p) => stmt.get(...p) ?? undefined, // bun returns null for "no row"
        all: (...p) => stmt.all(...p),
      };
    },
    pragma: (statement) => raw.prepare(`PRAGMA ${statement}`).all(),
    transaction: (fn) => raw.transaction(fn),
    close: () => raw.close(),
  };
}

interface ChunkRow {
  id: string;
  relative_path: string;
  language: string;
  text: string;
  start_line: number;
  end_line: number;
  symbol: string | null;
  chunk_type: string;
  vector: string;
}

function toChunk(row: ChunkRow): VectorStoreChunk {
  return {
    id: row.id,
    relativePath: row.relative_path,
    language: row.language,
    text: row.text,
    startLine: row.start_line,
    endLine: row.end_line,
    symbol: row.symbol ?? undefined,
    chunkType: row.chunk_type,
    vector: JSON.parse(row.vector),
  };
}

function cosineSimilarity(a: number[], b: number[]): number {
  let dot = 0;
  let normA = 0;
  let normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i]! * b[i]!;
    normA += a[i]! * a[i]!;
    normB += b[i]! * b[i]!;
  }
  if (normA === 0 || normB === 0) return 0;
  return dot / (Math.sqrt(normA) * Math.sqrt(normB));
}

/** Words hidden inside identifiers (camelCase), appended so FTS can match `http` in `retryHttpRequest`. */

function identifierWords(text: string): string {
  const words = new Set<string>();
  for (const token of text.match(/[A-Za-z][A-Za-z0-9]{2,}/g) ?? []) {
    const parts = token.split(/(?<=[a-z0-9])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])/);
    if (parts.length > 1) for (const p of parts) words.add(p.toLowerCase());
  }
  return [...words].join(" ");
}

function ftsQuery(query: string): string | null {
  const terms = extractTerms(query);
  if (terms.length === 0) return null;
  return terms.map((t) => `"${t.replace(/"/g, "")}"`).join(" OR ");
}

export function createVectorStore(options: VectorStoreOptions): VectorStore {
