const allStmt = db.prepare(`SELECT * FROM chunks`);
const byIdStmt = db.prepare(`SELECT * FROM chunks WHERE id = ?`);
const idPageStmt = db.prepare(
  `SELECT * FROM chunks WHERE id > ? ORDER BY id LIMIT ?`,
