      }[];
      return rows.map((row) => ({
        relativePath: row.relative_path,
        indexedAt: row.indexed_at,
        chunkCount: row.chunk_count,
      }));
    },

    close() {
      db.close();
    },
  };
}

export interface VectorStoreOptions {
  /** SQLite file path, or ":memory:" for an ephemeral in-process store (tests). */
  path: string;
  /** Rows loaded per page by `search()`; bounds peak memory (JSON vectors are parsed page by page). Default 500. */
  searchPageSize?: number;
  /**
   * Clock used to stamp `indexed_at` on every upsert (port-index-status-
   * tools, plan.md -- mirrors `file_index.last_indexed_at` in the
   * original Postgres schema). Injectable so tests don't depend on
   * wall-clock time; defaults to the real clock.
   */
  now?: () => string;
  /**
   * Version of the text format the stored vectors were embedded from (see
   * indexing/embed-input.ts). A store written with another version is
   * emptied on open so everything is re-embedded; omit to skip the check.
   */
  embedFormat?: number;
}

export interface IndexStatus {
  fileCount: number;
  chunkCount: number;
  newestIndexedAt: string | null;
}

export interface RecentChange {
  relativePath: string;
  indexedAt: string;
  chunkCount: number;
}

export interface IndexedFile {
  relativePath: string;
  language: string;
  chunkCount: number;
}

export interface VectorStore {
  /** One row per indexed file (no vectors loaded), sorted by path. */
  listFiles(): IndexedFile[];
  upsertChunks(chunks: VectorStoreChunk[]): void;
  deleteChunksForFile(relativePath: string): void;
  /** "size:mtime" recorded once a file was fully indexed; null if unknown. Dropped with the file's chunks. */
  getFileFingerprint(relativePath: string): string | null;
  setFileFingerprint(relativePath: string, fingerprint: string): void;
  getChunkIdsForFile(relativePath: string): Set<string>;
  getChunk(id: string): VectorStoreChunk | null;
  getAllChunks(): VectorStoreChunk[];
  /** Chunks with id > `afterId` (null = from the start), ordered by id; for streaming exports. */
  getChunksPage(afterId: string | null, limit: number): VectorStoreChunk[];
  search(queryVector: number[], topK: number): VectorSearchResult[];
  /** BM25 full-text search over text, symbol and path words (SQLite FTS5); [] if FTS5 is unavailable. */
  searchText(query: string, topK: number): VectorSearchResult[];
  /** file/chunk counts + newest indexed_at, across the whole store. */
  getIndexStatus(): IndexStatus;
  /** Most-recently-indexed files (one row per file), newest first. */
  getRecentChanges(limit: number): RecentChange[];
  close(): void;
}

import type { TelemetryEntry } from "./telemetry.js";

/** Tools of this plugin that replace blind searching. */
const CONTEXT_TOOLS = new Set([
  "semantic_search",
  "repo_structure",
  "analyze_impact",
  "search_docs",
  "find_symbol",
]);
/** Native tools an agent falls back to when searching by hand. */
const NATIVE_SEARCH_TOOLS = new Set(["grep", "glob", "list", "ls"]);

export interface SessionAdoption {
  sessionID: string;
  contextCalls: number;
  nativeSearchCalls: number;
  /** contextCalls / (contextCalls + nativeSearchCalls); null without any search call. */
  contextShare: number | null;
}

export interface Adoption extends Omit<SessionAdoption, "sessionID"> {
  contextByTool: Record<string, number>;
  bySession: SessionAdoption[];
}

function share(context: number, native: number): number | null {
  const total = context + native;
  return total === 0 ? null : context / total;
}

/** How often the agent used the context tools instead of grep/glob (ADR-0020). */

export function computeAdoption(entries: TelemetryEntry[]): Adoption {
  const contextByTool: Record<string, number> = {};
  const sessions = new Map<string, { context: number; native: number }>();
  let context = 0;
  let native = 0;

  for (const entry of entries) {
    const isContext = CONTEXT_TOOLS.has(entry.tool);
    const isNative = NATIVE_SEARCH_TOOLS.has(entry.tool);
    if (!isContext && !isNative) continue;
    const session = sessions.get(entry.sessionID) ?? { context: 0, native: 0 };
    if (isContext) {
      context++;
      session.context++;
      contextByTool[entry.tool] = (contextByTool[entry.tool] ?? 0) + 1;
    } else {
      native++;
      session.native++;
    }
    sessions.set(entry.sessionID, session);
  }

  return {
    contextCalls: context,
    nativeSearchCalls: native,
    contextShare: share(context, native),
    contextByTool: Object.fromEntries(
      Object.entries(contextByTool).sort(([a], [b]) => a.localeCompare(b)),
    ),
    bySession: [...sessions.entries()].map(([sessionID, s]) => ({
      sessionID,
      contextCalls: s.context,
      nativeSearchCalls: s.native,
      contextShare: share(s.context, s.native),
    })),
  };
}

export interface TelemetryRecorderOptions {
  /** Clock injection for deterministic tests. Defaults to Date.now. */
  now?: () => number;
  /** Defaults to @opentelemetry/api's global tracer (no-op without an SDK). */
  tracer?: OtelTracerLike;
  /** Defaults to @opentelemetry/api's global meter (no-op without an SDK). */
  meter?: OtelMeterLike;
}

export interface TelemetryRecorder {
  recordStart(event: TelemetryStartEvent): void;
  recordEnd(event: TelemetryEndEvent): void;
  getEntries(): TelemetryEntry[];
  getSummary(): TelemetrySummaryRow[];
  reset(): void;
}

export function createTelemetryRecorder(
  options: TelemetryRecorderOptions = {},
): TelemetryRecorder {
  const now = options.now ?? Date.now;
  const tracer: OtelTracerLike = options.tracer ?? trace.getTracer(INSTRUMENTATION_NAME);
  const meter: OtelMeterLike = options.meter ?? metrics.getMeter(INSTRUMENTATION_NAME);
  const durationHistogram = meter.createHistogram("opencode.tool.duration", {
    unit: "ms",
    description: "Duration of OpenCode tool calls observed via tool.execute.before/after hooks.",
  });

  const entries = new Map<string, TelemetryEntry>();
  const spans = new Map<string, OtelSpanLike>();

  return {
    recordStart({ tool, sessionID, callID, args }) {
      entries.set(callID, {
        tool,
        sessionID,
        callID,
        startedAt: now(),
        inputTokens: approxTokens(args),
      });
      spans.set(
        callID,
        tracer.startSpan(`tool.execute:${tool}`, { attributes: { tool, sessionID, callID } }),
      );
    },
    recordEnd({ callID, output }) {
      const entry = entries.get(callID);
      const span = spans.get(callID);
      spans.delete(callID);
      span?.end();
      if (!entry) return; // no matching start -- ignore defensively
      entry.endedAt = now();
      entry.durationMs = entry.endedAt - entry.startedAt;
      entry.outputTokens = approxTokens(output);
      durationHistogram.record(entry.durationMs, { tool: entry.tool, sessionID: entry.sessionID });
    },
    getEntries() {
      return Array.from(entries.values());
    },

    getSummary() {
      const byTool = new Map<
        string,
        { callCount: number; totalDurationMs: number; totalInputTokens: number; totalOutputTokens: number }
      >();
      for (const entry of entries.values()) {
        if (entry.durationMs === undefined) continue; // skip in-flight calls
        const row = byTool.get(entry.tool) ?? {
          callCount: 0,
          totalDurationMs: 0,
          totalInputTokens: 0,
          totalOutputTokens: 0,
        };
        row.callCount += 1;
        row.totalDurationMs += entry.durationMs;
        row.totalInputTokens += entry.inputTokens ?? 0;
        row.totalOutputTokens += entry.outputTokens ?? 0;
        byTool.set(entry.tool, row);
      }
      return Array.from(byTool.entries()).map(([tool, row]) => ({
        tool,
        callCount: row.callCount,
        totalDurationMs: row.totalDurationMs,
        avgDurationMs: row.totalDurationMs / row.callCount,
        totalInputTokens: row.totalInputTokens,
        totalOutputTokens: row.totalOutputTokens,
        totalTokens: row.totalInputTokens + row.totalOutputTokens,
      }));
    },
    reset() {
      entries.clear();
      spans.clear();
    },
  };
}

function approxTokens(text: unknown): number {
  if (text === null || text === undefined) return 0;
  const str = typeof text === "string" ? text : JSON.stringify(text);
  if (!str) return 0;
  const matches = str.match(/[A-Za-z]+|[0-9]+|[^ \t\n\rA-Za-z0-9]/g);
  return matches ? matches.length : str.length > 0 ? 1 : 0;
}

