export interface GitInfo {
  branch: string;
  commit: string;
}

export interface IndexTreeDeps {
  filePath: string;
  worktree: string;
  listFiles(): IndexedFile[];
  getIndexStatus(): IndexStatus;
  /** Files that were skipped or failed in the current indexing run. */
  getSkipped(): string[];
  gitInfo?: (worktree: string) => GitInfo;
  now?: () => Date;
}

export function readGitInfo(worktree: string): GitInfo {
  const git = (...args: string[]) => {
    try {
      return execFileSync("git", args, { cwd: worktree, stdio: ["ignore", "pipe", "ignore"], timeout: 5000 }).toString().trim() || "unknown";
    } catch {
      return "unknown";
    }
  };
  return { branch: git("rev-parse", "--abbrev-ref", "HEAD"), commit: git("rev-parse", "--short", "HEAD") };
}

interface Node {
  dirs: Map<string, Node>;
  files: IndexedFile[];
}

const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? "" : "s"}`;

export function renderIndexTree(files: IndexedFile[], meta: IndexTreeMeta): string {
  const root: Node = { dirs: new Map(), files: [] };
  for (const file of files) {
    const parts = file.relativePath.split("/");
    let node = root;
    for (const dir of parts.slice(0, -1)) {
      if (!node.dirs.has(dir)) node.dirs.set(dir, { dirs: new Map(), files: [] });
      node = node.dirs.get(dir)!;
    }
    node.files.push(file);
  }
  const lines: string[] = [];
  const walk = (node: Node, depth: number) => {
    const pad = "  ".repeat(depth);
    for (const [name, child] of [...node.dirs].sort(([a], [b]) => a.localeCompare(b))) {
      lines.push(`${pad}- ${name}/`);
      walk(child, depth + 1);
    }
    for (const f of [...node.files].sort((a, b) => a.relativePath.localeCompare(b.relativePath))) {
      lines.push(`${pad}- ${basename(f.relativePath)} (${f.language}, ${plural(f.chunkCount, "chunk")})`);
    }
  };
  walk(root, 0);
  const out = [
    "# Indexed files",
    "",
    "<!-- generated by opencode-ai-context-plugin; do not edit -->",
    "",
    `- Repository: ${meta.repoName} (${meta.repoPath})`,
    `- Branch: ${meta.branch} (${meta.commit})`,
    `- Exported: ${meta.exportedAt}`,
    `- Index last updated: ${meta.newestIndexedAt ?? "never"}`,
    `- Files: ${files.length} · Chunks: ${meta.chunkCount}`,
    "",
    "## Tree",
    "",
    ...(lines.length ? lines : ["_nothing indexed yet_"]),
  ];
  if (meta.skipped.length) {

export interface IndexTreeMeta {
  repoName: string;
  repoPath: string;
  branch: string;
  commit: string;
  exportedAt: string;
  newestIndexedAt: string | null;
  chunkCount: number;
  skipped: string[];
}

    out.push("", "## Not indexed", "", ...meta.skipped.map((s) => `- ${s}`));
  }
  return out.join("\n") + "\n";
}

export function writeIndexTree(deps: IndexTreeDeps): { filePath: string; fileCount: number } {
  const files = deps.listFiles();
  const status = deps.getIndexStatus();
  const git = (deps.gitInfo ?? readGitInfo)(deps.worktree);
  const md = renderIndexTree(files, {
    repoName: basename(deps.worktree),
    repoPath: deps.worktree,
    branch: git.branch,
    commit: git.commit,
    exportedAt: (deps.now ?? (() => new Date()))().toISOString(),
    newestIndexedAt: status.newestIndexedAt,
    chunkCount: status.chunkCount,
    skipped: deps.getSkipped(),
  });
  mkdirSync(dirname(deps.filePath), { recursive: true });
  writeFileSync(deps.filePath, md);
  return { filePath: deps.filePath, fileCount: files.length };
}

import { tool } from "@opencode-ai/plugin";
import { attachIndexingNotice } from "../indexing/index-notice.js";
import { findTestFiles } from "./test-files.js";
import type { GraphStore } from "../storage/graph-store.js";

/**
 * `find_symbol`: cheap name lookup (class/function/method definitions) from
 * the symbol index. Answers "where is X defined" without an LSP round trip
 * or a language server being up.
 */

export interface FindSymbolDeps {
  graphStore: GraphStore;
  /** Symbol indexes of other allowed projects (cross-repo allowlist), selectable via `project`. */
  crossRepoGraphs?: { key: string; store: GraphStore }[];
  getIndexingNotice?: () => string | null;
}

export function createFindSymbolTool(deps: FindSymbolDeps) {
  return tool({
    description: [
      "Find where a class, function or method is defined by (part of) its name,",
      "from the symbol index: file, line range, kind and enclosing container.",
      "Case-insensitive substring match, exact and prefix matches first.",
      "`tests` lists test files that import or call the matches.",
      "Fast and needs no language server; use `read` on the returned file and lines.",
      "Pass `project` to search another allowed repo. For callers/dependents use `analyze_impact`; for exact references use the",
      "native `lsp` tool; for conceptual questions without a known name use `semantic_search`.",
    ].join(" "),
    args: {
      query: tool.schema.string().describe("Symbol name or part of it, e.g. `UserService` or `parseConf`."),
      kind: tool.schema
        .string()
        .optional()
        .describe("Only this kind, e.g. `class`, `function`, `method`."),
      project: tool.schema
        .string()
        .optional()
        .describe("Name of another allowed project (see ai_context_list_projects, field `name`, no hash); default: this project."),
      limit: tool.schema.number().int().positive().max(100).default(20).describe("Maximum matches."),
    },
    async execute(args) {
      const limit = args.limit ?? 20;
      let graph = deps.graphStore;
      if (args.project) {
        const others = deps.crossRepoGraphs ?? [];
        const other = others.find((g) => g.key === args.project);

        if (!other) {
          const known = others.map((g) => g.key).join(", ") || "none";
          return JSON.stringify({
            error: `Unknown or not allowed project "${args.project}". Allowed: ${known}.`,
          });
        }
        graph = other.store;
      }
      const pool = graph.searchSymbols(args.query, args.kind ? limit * 5 : limit);
      const matches = pool
        .filter((s) => !args.kind || s.kind === args.kind)
        .slice(0, limit)
        .map((s) => ({
          name: s.name,
          kind: s.kind,
          path: s.relativePath,
          startLine: s.startLine,
          endLine: s.endLine,
          container: s.container,
        }));
      const result: Record<string, unknown> = { matches };
      if (args.project) result.project = args.project;
      if (matches.length > 0) {
        result.tests = findTestFiles(
          graph,
          matches.map((m) => m.path),
          matches.map((m) => m.name),
        );
      }
      if (matches.length === 0) {
        result.hint =
          "No symbol matched. Try a shorter name, or use semantic_search for a conceptual query; the index may still be building (see index_status).";
      }
      return JSON.stringify(attachIndexingNotice(result, deps.getIndexingNotice?.() ?? null));
    },
  });
}

import { tool } from "@opencode-ai/plugin";
import type { IndexStatus, RecentChange } from "../storage/vector-store.js";
import type { IndexProgressSnapshot } from "../indexing/index-progress.js";
import type { RescanStats } from "../indexing/rescan-trigger.js";

/**
 * index_status (plan.md, "port-index-status-tools"): ports
 * mcp-server/src/db.ts's getIndexStatus + getRecentChanges into a single
 * native tool -- index-health/observability for the CURRENT project's
 * store, distinct from ai_context_list_projects (which lists every
 * project on the machine, not one project's indexing detail) and
 * ai_context_telemetry_report (tool-call latency/counts, not indexing state).
 */

export interface IndexStatusDeps {
  getIndexStatus: () => IndexStatus;
  getRecentChanges: (limit: number) => RecentChange[];
  /** Live indexing progress (index-progress.ts); omit to leave the `indexing` block out. */
  getProgress?: () => IndexProgressSnapshot;
  /** Where the progress is mirrored on disk, so the agent can point the user at it. */
  statusFilePath?: string;
  /** How changes reach the index: watcher events seen so far and the rescan fallback. */
  getWatcher?: () => { eventsReceived: number; lastEventAt: string | null; rescan: RescanStats };
}

const DEFAULT_RECENT_CHANGES_LIMIT = 10;

export function createIndexStatusTool(deps: IndexStatusDeps) {
  return tool({
    description: [
      "Report whether this project's index is complete and current. Call it",
      "when semantic_search, search_docs or analyze_impact return empty or",
      "partial results, or when an indexingNotice appears, to see if indexing",
      "is still running, how far it is and which files failed or were",
      "skipped -- a missing hit does not prove the code does not exist.",
      "Returns indexed file/chunk counts, the newest indexed_at, the most",
      "recently indexed files (path, indexed_at, chunk count) and an",
      "`indexing` block (phase, done/total, percent, ETA, failures, notices).",
      "A notice is an actionable hint for the user, e.g. a missing API key: relay it.",
      "`watcher` shows how many file-watcher events arrived (0 means opencode's",
      "watcher is silent) and the last rescan; if files are missing, call",
      "ai_context_rescan.",
    ].join(" "),
    args: {
      limit: tool.schema
        .number()
        .optional()
        .describe(
          `Max number of recentChanges rows to return (default ${DEFAULT_RECENT_CHANGES_LIMIT}).`,
        ),
    },
    async execute(args) {
      const limit = args.limit ?? DEFAULT_RECENT_CHANGES_LIMIT;
      const status = deps.getIndexStatus();
      const recentChanges = deps.getRecentChanges(limit);
      const progress = deps.getProgress?.();
      const indexing = progress && {
        running: progress.running,

        phase: progress.phase,
        done: progress.done,
        total: progress.total,
        percent: progress.percent,
        etaSeconds: progress.etaSeconds,
        currentFile: progress.currentFile,
        failed: progress.failed,
        failures: progress.failures,
        lastError: progress.lastError,
        notices: progress.notices,
        statusFile: deps.statusFilePath,
      };
      return JSON.stringify({
        ...status,
        recentChanges,
        ...(indexing ? { indexing } : {}),
        ...(deps.getWatcher ? { watcher: deps.getWatcher() } : {}),
      });
    },
  });
}

