    if (idleTimer) clearTimeout(idleTimer);
    for (const s of sockets) s.destroy();
    await new Promise<void>((resolve) => server.close(() => resolve()));
    fs.rmSync(socketPath, { force: true });
    if (reason) options.onExit?.(reason);
  };

