  await createIndexer({ ...base, progress }).indexFiles([{ file: "a.ts", event: "add" }, { file: "b.ts", event: "add" }]);
  assert.deepEqual(calls, [{ n: 1, reasons: { changed: 1 } }]);
  assert.deepEqual(done, ["b.ts"]);
});

