import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { deriveProjectKey } from "../../src/storage/project-key.js";
import { listProjects, deleteProject } from "../../src/storage/project-registry.js";

function seedProject(dataDir: string, worktree: string, bytes = 100): ReturnType<typeof deriveProjectKey> {
  const result = deriveProjectKey(worktree, { dataDir });
  fs.mkdirSync(path.dirname(result.dbPath), { recursive: true });
  fs.writeFileSync(result.dbPath, Buffer.alloc(bytes));
  return result;
}

test("listProjects returns an empty array when no projects have been indexed yet", () => {
  const dataDir = tmpDataDir();
  assert.deepEqual(listProjects({ dataDir }), []);
  fs.rmSync(dataDir, { recursive: true, force: true });
});

test("listProjects lists every project directory under the data dir with its size", () => {
  const dataDir = tmpDataDir();
  const a = seedProject(dataDir, "/tmp/repo-a", 200);
  const b = seedProject(dataDir, "/tmp/repo-b", 500);

  const projects = listProjects({ dataDir });
  const keys = projects.map((p) => p.key).sort();
  assert.deepEqual(keys, [a.key, b.key].sort());

  const found = projects.find((p) => p.key === b.key)!;
  assert.equal(found.dbPath, b.dbPath);
  assert.ok(found.sizeBytes >= 500, "sizeBytes should reflect the on-disk db file size");

  fs.rmSync(dataDir, { recursive: true, force: true });
});

test("deleteProject removes a project's directory and returns true", () => {
  const dataDir = tmpDataDir();
  const a = seedProject(dataDir, "/tmp/repo-a");

  const deleted = deleteProject(a.key, { dataDir });
  assert.equal(deleted, true);
  assert.deepEqual(listProjects({ dataDir }), []);

  fs.rmSync(dataDir, { recursive: true, force: true });
});

test("deleteProject returns false for an unknown key instead of throwing", () => {
  const dataDir = tmpDataDir();
  assert.equal(deleteProject("does-not-exist-12345678", { dataDir }), false);
  fs.rmSync(dataDir, { recursive: true, force: true });
});

test("deleteProject rejects keys that could escape the projects directory (path traversal)", () => {
  const dataDir = tmpDataDir();
  assert.throws(() => deleteProject("../../etc", { dataDir }), /invalid project key/i);
  assert.throws(() => deleteProject("nested/path", { dataDir }), /invalid project key/i);
  fs.rmSync(dataDir, { recursive: true, force: true });
});

test("listProjects ignores files that vanish while sizing (e.g. the index lock being released)", () => {
  const dataDir = tmpDataDir();
  const a = seedProject(dataDir, "/tmp/repo-vanish", 100);
  fs.symlinkSync("/nonexistent/target", path.join(path.dirname(a.dbPath), "index.lock"));
  const [project] = listProjects({ dataDir });
  assert.equal(project!.sizeBytes, 100);
  fs.rmSync(dataDir, { recursive: true, force: true });
});

test("listProjects exposes the stable name (key without the hash suffix)", () => {
  const dataDir = tmpDataDir();
  fs.mkdirSync(path.join(dataDir, "projects", "tlt-platform-cb270a90"), { recursive: true });
  const [project] = listProjects({ dataDir });
  assert.equal(project!.name, "tlt-platform");
  assert.equal(project!.key, "tlt-platform-cb270a90");
  fs.rmSync(dataDir, { recursive: true, force: true });
});

function tmpDataDir(): string {
  const dir = `${process.env.TMPDIR ?? "/tmp"}/ai-context-registry-test-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { chunkWithRegexPatterns } from "../../src/indexing/regex-chunker.js";

test("chunkWithRegexPatterns splits a PHP file at top-level class/interface/trait/function boundaries", () => {
  const content = ["abstract class Foo {}", "", "function bar() {}", ""].join("\n");
  const chunks = chunkWithRegexPatterns(content, ".php");
  assert.ok(chunks);
  assert.deepEqual(
    chunks!.map((c) => c.symbol),
    ["Foo", "bar"],
  );
});

test("chunkWithRegexPatterns splits a C file at struct/enum/union declarations and function definitions", () => {
  const content = ["struct Point { int x; int y; };", "", "int add(int a, int b) {", "  return a + b;", "}", ""].join(
    "\n",
  );
  const chunks = chunkWithRegexPatterns(content, ".c");
  assert.ok(chunks);
  assert.deepEqual(
    chunks!.map((c) => c.symbol),
    ["Point", "add"],
  );
});

test("chunkWithRegexPatterns does not mistake C control-flow keywords for a function name", () => {
  const content = ["int main() {", "  if (x > 0) {", "    return 1;", "  }", "  return 0;", "}", ""].join("\n");
  const chunks = chunkWithRegexPatterns(content, ".c");
  assert.ok(chunks);
  assert.deepEqual(
    chunks!.map((c) => c.symbol),
    ["main"],
  );
});

test("chunkWithRegexPatterns returns null for an extension with no regex-chunking table entry", () => {
  const chunks = chunkWithRegexPatterns("<html></html>", ".html");
  assert.equal(chunks, null);
});

test("chunkWithRegexPatterns returns null when the file has zero top-level declarations (triggering chunkText fallback)", () => {
  const chunks = chunkWithRegexPatterns("print('no declarations here')\n", ".py");
  assert.equal(chunks, null);
});

test("chunkWithRegexPatterns emits a preamble chunk for content before the first declaration", () => {
  const content = ["import os", "", "def foo():", "    pass", ""].join("\n");
  const chunks = chunkWithRegexPatterns(content, ".py");
  assert.ok(chunks);
  assert.equal(chunks![0]!.chunkType, "block");
  assert.equal(chunks![0]!.symbol, undefined);
  assert.ok(chunks![0]!.text.includes("import os"));
  assert.equal(chunks![1]!.symbol, "foo");
});

test("chunkWithRegexPatterns matches a const arrow-function assignment as a function chunk (shared by JS and TS top-level pattern)", () => {
  const content = ["const handler = (x) => x + 1;", ""].join("\n");
  const chunks = chunkWithRegexPatterns(content, ".js");
  assert.ok(chunks);
  assert.deepEqual(
    chunks!.map((c) => [c.symbol, c.chunkType]),
    [["handler", "function"]],
  );
});

test("chunkWithRegexPatterns splits a Kotlin file at class/object/interface/fun/typealias boundaries", () => {
  const content = [
    "class Foo {",
    "  fun method() {}",
    "}",
    "",
    "object Bar",
    "interface Baz",
    "fun standalone() {}",
    "typealias Alias = String",
    "",
  ].join("\n");
  const chunks = chunkWithRegexPatterns(content, ".kt");
  assert.ok(chunks);
  assert.deepEqual(
    chunks!.map((c) => c.symbol),
    ["Foo", "Bar", "Baz", "standalone", "Alias"],
  );
  assert.deepEqual(
    chunks!.map((c) => c.chunkType),
    ["class", "class", "class", "function", "class"],
  );
});

test("chunkWithRegexPatterns splits a JavaScript file the same way as the TypeScript top-level pattern", () => {
  const content = ["export class Foo {}", "", "export function bar() {}", "const baz = () => {}", ""].join("\n");
  const chunks = chunkWithRegexPatterns(content, ".js");
  assert.ok(chunks);
  assert.deepEqual(
    chunks!.map((c) => c.symbol),
    ["Foo", "bar", "baz"],
