      mkdirSync: (p: string) => void log.push(`mkdir ${p}`),
      writeFileSync: (p: string, data: string) => {
        log.push(`write ${p}`);
        files.set(p, data);
      },
      renameSync: (from: string, to: string) => {
        log.push(`rename ${from} -> ${to}`);
        files.set(to, files.get(from)!);
        files.delete(from);
      },
    },
  };
}

